import type { BankQuestion } from "@/lib/bank";

/** MS Office, Internet and Cyber Security (Computer Awareness): 500 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "comp-ms-office-internet-1", "question": "Which keyboard shortcut selects all the content of a document in MS Word?", "options": ["Ctrl + L", "Ctrl + E", "Ctrl + A", "Ctrl + S"], "answer": 2, "explanation": "Ctrl + A selects all. Ctrl + S saves, Ctrl + L left-aligns and Ctrl + E centres the text.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-2", "question": "What is the default file extension of an MS Excel workbook saved in Excel 2007 or later?", "options": [".docx", ".accdb", ".pptx", ".xlsx"], "answer": 3, "explanation": ".xlsx is the Excel workbook format (Office Open XML). .docx is Word, .pptx is PowerPoint and .accdb is an Access database.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-3", "question": "A malicious program that looks like useful software but secretly harms the system once installed is called a:", "options": ["Firewall", "Trojan horse", "Worm", "Cookie"], "answer": 1, "explanation": "A Trojan horse disguises itself as legitimate software. A worm spreads by itself across networks; a firewall is a defence and a cookie is a small browser file.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-4", "question": "Which key starts a PowerPoint slide show from the first slide?", "options": ["F5", "F12", "F1", "F7"], "answer": 0, "explanation": "F5 runs the slide show from the beginning (Shift + F5 starts from the current slide). F7 is spell check, F12 is Save As and F1 is Help.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-5", "question": "Which MS Excel function counts only the cells in a range that contain numbers?", "options": ["COUNT", "COUNTA", "COUNTBLANK", "SUM"], "answer": 0, "explanation": "COUNT counts numeric cells only. COUNTA counts every non-empty cell (text included), COUNTBLANK counts empty cells and SUM adds values.", "difficulty": "moderate", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-6", "question": "An e-mail pretending to be from your bank that asks you to click a link and enter your login details is an example of:", "options": ["Spamdexing", "Cracking", "Phishing", "Vishing"], "answer": 2, "explanation": "Phishing uses fake e-mails or websites to steal credentials. Vishing is the same trick over voice calls.", "difficulty": "moderate", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-7", "question": "In MS Word, the shortcut Ctrl + E is used to:", "options": ["Right-align the text", "Justify the text", "Open the Find dialog", "Centre-align the text"], "answer": 3, "explanation": "Ctrl + E centres, Ctrl + J justifies, Ctrl + R right-aligns, Ctrl + L left-aligns and Ctrl + F opens Find.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-8", "question": "Which protocol lets you read e-mail while keeping the messages on the server, so the mailbox stays in sync on your phone and laptop?", "options": ["POP3", "IMAP", "SMTP", "FTP"], "answer": 1, "explanation": "IMAP keeps mail on the server and syncs folders across devices. POP3 typically downloads mail to one device and removes it from the server; SMTP only sends mail.", "difficulty": "moderate", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-9", "question": "PDF, the common document format developed by Adobe, stands for:", "options": ["Printable Document File", "Portable Document Format", "Portable Data File", "Public Data Format"], "answer": 1, "explanation": "PDF = Portable Document Format, introduced by Adobe in 1993 so a document looks the same on every device.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-10", "question": "Which device forwards data packets between different networks using IP addresses?", "options": ["Hub", "Repeater", "Switch", "Router"], "answer": 3, "explanation": "A router works at the network layer and routes packets between networks by IP address. A switch forwards frames within a LAN using MAC addresses; a hub and repeater only regenerate signals.", "difficulty": "moderate", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-11", "question": "A system that monitors incoming and outgoing network traffic and blocks it according to set security rules is a:", "options": ["Firewall", "Compiler", "Modem", "Proxy server"], "answer": 0, "explanation": "A firewall (hardware or software) filters traffic by rules. A proxy forwards requests on a client's behalf; it is not primarily a rule-based filter.", "difficulty": "moderate", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-12", "question": "In MS Excel, which cell reference remains unchanged when a formula is copied to another cell?", "options": ["A$1", "$A1", "$A$1", "A1"], "answer": 2, "explanation": "$A$1 is an absolute reference: both column and row are locked. A1 is relative, while A$1 and $A1 are mixed references that lock only the row or only the column.", "difficulty": "moderate", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-13", "question": "What value does the Excel formula =INT(-4.3) return?", "options": ["-5", "-4", "-4.3", "4"], "answer": 0, "explanation": "INT rounds a number down to the nearest integer, so -4.3 becomes -5 (not -4). TRUNC(-4.3) would give -4.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-14", "question": "The WannaCry attack of May 2017, which locked files on computers worldwide and demanded payment in Bitcoin, was an example of:", "options": ["Keylogger", "Ransomware", "Adware", "Spyware"], "answer": 1, "explanation": "Ransomware encrypts the victim's files and demands a ransom for the key. WannaCry spread through a Windows SMB vulnerability.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-16", "question": "Which Excel function searches for a value in the top row of a table and returns a value from a specified row below it?", "options": ["MATCH", "VLOOKUP", "HLOOKUP", "CONCAT"], "answer": 2, "explanation": "HLOOKUP looks across the first row (horizontal). VLOOKUP looks down the first column; MATCH returns only a position.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-17", "question": "An IPv6 address is how many bits long?", "options": ["256", "64", "128", "32"], "answer": 2, "explanation": "IPv6 addresses are 128 bits, written as eight groups of four hexadecimal digits. IPv4 addresses are 32 bits.", "difficulty": "hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-18", "question": "Which type of malware copies itself from computer to computer over a network without attaching to a host file and without user action?", "options": ["Adware", "Worm", "Trojan horse", "Virus"], "answer": 1, "explanation": "A worm is self-replicating and standalone. A virus needs a host file and usually needs that file to be run; a Trojan does not replicate.", "difficulty": "hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-19", "question": "Logging in with a password followed by an OTP sent to your registered mobile number is an example of:", "options": ["Two-factor authentication", "Single sign-on", "Biometric authentication", "CAPTCHA verification"], "answer": 0, "explanation": "It combines something you know (password) with something you have (the phone receiving the OTP), which is two-factor authentication.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-20", "question": "In MS Word, pressing F7 opens:", "options": ["Help", "Save As dialog", "Thesaurus", "Spelling and Grammar check"], "answer": 3, "explanation": "F7 runs Spelling and Grammar. Shift + F7 opens the Thesaurus, F12 is Save As and F1 is Help.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-21", "question": "In Excel, A1 = 10, A2 is blank, A3 = “Yes”, A4 = 0 and A5 is blank. What does =COUNTA(A1:A5) return?", "options": ["2", "3", "5", "1"], "answer": 1, "explanation": "COUNTA counts non-empty cells: A1, A3 and A4 → 3. COUNT would return 2 because it ignores the text in A3; a zero is still a value.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-22", "question": "A small text file that a website stores in your browser to remember your login or preferences is called a:", "options": ["Cache", "Plug-in", "Applet", "Cookie"], "answer": 3, "explanation": "Cookies are small text files stored by websites. The cache stores copies of web pages and images to load them faster.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-23", "question": "Which image format uses lossy compression and is the most common choice for photographs?", "options": ["JPEG", "BMP", "GIF", "PNG"], "answer": 0, "explanation": "JPEG discards some detail to shrink file size (lossy). PNG and GIF are lossless (GIF is limited to 256 colours) and BMP is usually uncompressed.", "difficulty": "hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-24", "question": "A network that covers a city, such as a cable TV network or a city-wide network linking a bank's branches, is a:", "options": ["PAN", "LAN", "MAN", "WAN"], "answer": 2, "explanation": "MAN (Metropolitan Area Network) spans a city. LAN covers a building or campus, PAN a person's devices and WAN countries or continents.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id":"comp-ms-office-internet-25","question":"How many of these MS Word shortcuts are correctly described? I. Ctrl + Home moves the cursor to the beginning of the document. II. Ctrl + Enter inserts a section break. III. Ctrl + K inserts a hyperlink. IV. Ctrl + D duplicates the selected line.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. II is wrong: Ctrl + Enter inserts a page break; section breaks are inserted from the Layout tab. IV is wrong: Ctrl + D in Word opens the Font dialog box.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-26", "question": "Match the malware with its description: 1. Keylogger 2. Rootkit 3. Adware 4. Spyware; a. Hides deep in the operating system to keep privileged access b. Shows unwanted advertisements c. Records every keystroke d. Secretly collects user information and sends it to a third party", "options": ["1-a, 2-c, 3-b, 4-d", "1-c, 2-a, 3-d, 4-b", "1-c, 2-a, 3-b, 4-d", "1-d, 2-a, 3-b, 4-c"], "answer": 2, "explanation": "Keylogger records keystrokes (c), rootkit hides in the OS with admin-level access (a), adware shows ads (b), spyware gathers information and sends it out (d).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-27", "question": "In Excel, A1 = 5, A2 = 10, A3 = 15, A4 contains the text “abc” and A5 is blank. What does =AVERAGE(A1:A5) return?", "options": ["7.5", "6", "#VALUE!", "10"], "answer": 3, "explanation": "AVERAGE ignores text and empty cells in a range: (5 + 10 + 15)/3 = 10. Dividing by 5 cells (6) or 4 cells (7.5) is the trap.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-28", "question": "Every cell from A1 to C4 contains the number 2. What does the formula =SUM(A1:C4)/COUNT(B1:B4) return?", "options": ["12", "6", "8", "3"], "answer": 1, "explanation": "A1:C4 has 3 columns × 4 rows = 12 cells, so SUM = 24. COUNT(B1:B4) = 4. 24 ÷ 4 = 6.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-29", "question": "In Excel, A1 = 60 and B1 = 45. What does =IF(AND(A1>50,B1>50),\"Pass\",\"Fail\") return?", "options": ["Fail", "FALSE", "Pass", "#VALUE!"], "answer": 0, "explanation": "AND needs both conditions true; B1 > 50 is false, so AND returns FALSE and IF gives “Fail”. With OR instead of AND, the result would be “Pass”.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-30", "question": "Arrange in chronological order: 1. First message sent over ARPANET 2. Tim Berners-Lee proposes the World Wide Web at CERN 3. ARPANET switches to TCP/IP 4. VSNL launches public internet service in India", "options": ["1, 2, 3, 4", "1, 3, 4, 2", "3, 1, 2, 4", "1, 3, 2, 4"], "answer": 3, "explanation": "ARPANET's first message (1969), ARPANET adopts TCP/IP (1 January 1983), WWW proposal (1989), VSNL public internet in India (15 August 1995). Order: 1, 3, 2, 4.", "difficulty": "very-hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-31", "question": "How many of these statements are correct? I. Phishing through SMS messages is called smishing. II. Vishing uses voice calls to trick victims. III. A DDoS attack floods a server with traffic from many compromised machines. IV. Pharming means tricking a person into revealing an OTP over a phone call.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: pharming redirects users to a fake website even when they type the correct address, often through DNS poisoning; the phone-call trick is vishing.", "difficulty": "very-hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-32", "question": "Assertion (A): HTTPS is safer than HTTP for internet banking. Reason (R): HTTPS uses port 80 by default.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 2, "explanation": "A is true because HTTPS encrypts traffic with TLS. R is false: HTTPS uses port 443; port 80 is plain HTTP.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-33", "question": "How many of these are valid IPv4 addresses? 192.168.0.255, 256.10.1.1, 10.10.10, 172.31.0.1", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "An IPv4 address has four octets, each from 0 to 255. 192.168.0.255 and 172.31.0.1 are valid; 256.10.1.1 has an octet above 255 and 10.10.10 has only three octets. So only two.", "difficulty": "very-hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-34", "question": "Match the file extension with what it stores: 1. .pptx 2. .accdb 3. .xlsm 4. .dotx; a. Access database b. Macro-enabled Excel workbook c. Word template d. PowerPoint presentation", "options": ["1-d, 2-a, 3-c, 4-b", "1-d, 2-b, 3-a, 4-c", "1-d, 2-a, 3-b, 4-c", "1-a, 2-d, 3-b, 4-c"], "answer": 2, "explanation": ".pptx is a PowerPoint presentation, .accdb an Access database, .xlsm an Excel workbook with macros enabled and .dotx a Word template.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-35", "question": "In Excel, A1 = 25 and B1 is empty. What does =A1/B1 return?", "options": ["#DIV/0!", "25", "0", "#VALUE!"], "answer": 0, "explanation": "An empty cell is treated as 0 in arithmetic, so the formula divides by zero and returns #DIV/0!. #VALUE! appears when a wrong data type, such as text, is used.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-36", "question": "A broadband connection has a speed of 100 Mbps. What is the maximum amount of data it can transfer per second, in megabytes?", "options": ["800 MB", "12.5 MB", "10 MB", "100 MB"], "answer": 1, "explanation": "Mbps is megabits per second and 1 byte = 8 bits, so 100 ÷ 8 = 12.5 megabytes per second.", "difficulty": "very-hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-37", "question": "How many of these statements about e-mail are correct? I. Recipients in the CC field are visible to all recipients. II. Recipients in the BCC field are hidden from the other recipients. III. SMTP is the protocol a mail client uses to download messages from the server. IV. POP3 uses port 110 by default.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. III is wrong: SMTP sends mail; POP3 or IMAP is used to retrieve it.", "difficulty": "very-hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-38", "question": "In which case did the Supreme Court strike down Section 66A of the Information Technology Act, 2000 in 2015?", "options": ["Shreya Singhal v. Union of India", "Anuradha Bhasin v. Union of India", "Justice K.S. Puttaswamy v. Union of India", "Vishaka v. State of Rajasthan"], "answer": 0, "explanation": "Shreya Singhal (2015) struck down Section 66A, which punished “offensive” online messages, as violating free speech. Puttaswamy (2017) declared privacy a fundamental right; Anuradha Bhasin (2020) dealt with internet shutdowns.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-39", "question": "Assertion (A): A computer virus usually cannot spread until an infected file or program is executed. Reason (R): A virus attaches its code to a host program or file.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true. Because a virus lives inside a host program, its code runs, and copies itself, only when that host is run, so R explains A. This is what separates it from a worm.", "difficulty": "very-hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-40", "question": "How many of these statements are correct? I. CERT-In works under the Ministry of Electronics and Information Technology. II. The IT Act, 2000 gave legal recognition to electronic records and digital signatures. III. 1930 is the national cyber-crime helpline number. IV. The Digital Personal Data Protection Act was passed in 2023.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct: CERT-In is under MeitY, the IT Act 2000 recognises e-records and digital signatures, 1930 is the cyber-fraud helpline and the DPDP Act was enacted in August 2023.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id":"comp-ms-office-internet-41","question":"In MS Word, which shortcut inserts a manual page break at the cursor position?","options":["Ctrl + Enter","Shift + Enter","Alt + Enter","Ctrl + Shift + Enter"],"answer":0,"explanation":"Ctrl + Enter starts a new page. Shift + Enter inserts only a line break within the same paragraph, and Ctrl + Shift + Enter inserts a column break.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-42","question":"In MS PowerPoint, which shortcut adds a new slide to the presentation?","options":["Ctrl + D","Ctrl + N","Ctrl + S","Ctrl + M"],"answer":3,"explanation":"Ctrl + M inserts a new slide. Ctrl + N opens a new presentation, Ctrl + S saves and Ctrl + D duplicates the selected slide or object.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-43","question":"In MS Excel, which function key lets you edit the contents of the active cell directly?","options":["F7","F4","F2","F12"],"answer":2,"explanation":"F2 puts the active cell into edit mode. F4 repeats the last action or toggles references, F7 runs spell-check and F12 opens Save As.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-44","question":"In a web address such as https://www.example.gov.in, the part '.in' is the:","options":["Protocol","Country-code top-level domain","Sub-domain","File path"],"answer":1,"explanation":".in is India's country-code top-level domain (ccTLD). 'https' is the protocol and 'www' is a sub-domain; there is no path in this address.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-45","question":"The HTTP status code shown when the requested web page does not exist on the server is:","options":["500","200","301","404"],"answer":3,"explanation":"404 means Not Found. 200 means OK (success), 301 means the page has moved permanently, and 500 is an internal server error.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-46","question":"Which view in MS PowerPoint shows thumbnails of all slides together so that they can be rearranged easily?","options":["Slide Sorter view","Notes Page view","Reading view","Outline view"],"answer":0,"explanation":"Slide Sorter displays every slide as a thumbnail for reordering, deleting or duplicating. Notes Page shows one slide with its speaker notes; Reading view plays the show in a window.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-47","question":"Which of the following is an example of 'something you are' in authentication?","options":["OTP received on mobile","Password","Fingerprint scan","Smart card"],"answer":2,"explanation":"Biometrics like fingerprints are inherence factors ('something you are'). A password is something you know; an OTP device and a smart card are something you have.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-48","question":"In MS Excel, which shortcut inserts the current date in the active cell?","options":["Ctrl + Shift + ;","Ctrl + ;","Ctrl + D","Alt + ;"],"answer":1,"explanation":"Ctrl + ; enters today's date as a fixed value. Ctrl + Shift + ; enters the current time, and Ctrl + D fills down.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-49","question":"Which national helpline number can a victim of online financial fraud in India dial to report it?","options":["100","1930","1098","112"],"answer":1,"explanation":"1930 is the national cyber crime helpline for reporting financial cyber fraud (complaints can also be lodged on cybercrime.gov.in). 1098 is Childline and 112 is the general emergency number.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-50","question":"Which feature of MS Word combines a standard letter with a list of names and addresses to create personalised copies?","options":["Thesaurus","Track Changes","Macro","Mail Merge"],"answer":3,"explanation":"Mail Merge joins a main document with a data source (such as an Excel list). Track Changes records edits, and a macro automates repeated tasks.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-51","question":"The protocol whose default port number is 22 and which provides secure remote login is:","options":["SSH","Telnet","FTP","SMTP"],"answer":0,"explanation":"SSH runs on port 22 and encrypts the session. Telnet (port 23) does a similar job but sends everything, including passwords, in plain text.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-52","question":"In MS Word, what does the shortcut Shift + F3 do to selected text?","options":["Applies strikethrough","Opens the Find dialog","Changes its case, cycling through lowercase, UPPERCASE and Capitalise Each Word","Opens the thesaurus"],"answer":2,"explanation":"Shift + F3 cycles the case of the selection. Shift + F7 opens the thesaurus and Ctrl + F opens Find.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-53","question":"In MS Word, which shortcut makes the selected text subscript (as in H₂O)?","options":["Ctrl + Shift + S","Ctrl + Shift + =","Ctrl + ]","Ctrl + ="],"answer":3,"explanation":"Ctrl + = toggles subscript; Ctrl + Shift + = (that is, Ctrl + +) toggles superscript. Ctrl + ] increases the font size by one point.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-54","question":"In MS Word, which shortcut sets 1.5 line spacing for the selected paragraph?","options":["Ctrl + 5","Ctrl + 1","Ctrl + 2","Ctrl + 3"],"answer":0,"explanation":"Ctrl + 1 gives single spacing, Ctrl + 2 double spacing and Ctrl + 5 gives 1.5 line spacing. Ctrl + 3 is not a line-spacing shortcut.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-55","question":"During a PowerPoint slide show, pressing the 'B' key:","options":["Bolds the text on the current slide","Jumps back to the first slide","Turns the screen black; pressing it again returns to the show","Ends the slide show"],"answer":2,"explanation":"B (or the full stop key) blacks out the screen and W (or comma) whitens it; pressing the key again resumes. Esc ends the show; Home goes to the first slide.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-56","question":"In MS PowerPoint, which shortcut starts the slide show from the CURRENT slide rather than from the first?","options":["F5","Shift + F5","Ctrl + F5","Alt + F5"],"answer":1,"explanation":"Shift + F5 starts from the selected slide; F5 always starts from slide 1.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-57","question":"In MS Excel, which shortcut turns AutoFilter on or off for the selected data range?","options":["Ctrl + Shift + L","Ctrl + Shift + F","Alt + F","Ctrl + L"],"answer":0,"explanation":"Ctrl + Shift + L toggles the filter dropdowns. Ctrl + L (like Ctrl + T) creates a table, which also adds filters, but it does not toggle them off.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-58","question":"In MS Excel, pressing Alt + = in the cell below a column of numbers:","options":["Opens the Insert Function dialog","Inserts the AutoSum (SUM) formula for the numbers above","Shows all formulas instead of values","Copies the formula from the cell above"],"answer":1,"explanation":"Alt + = inserts =SUM() over the adjacent range. Shift + F3 opens Insert Function, Ctrl + ` shows formulas, and Ctrl + D copies the cell above.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-59","question":"In MS Excel, which shortcut opens the Format Cells dialog box?","options":["Ctrl + Shift + F1","Ctrl + F","Ctrl + 1","Alt + 1"],"answer":2,"explanation":"Ctrl + 1 opens Format Cells (number, alignment, font, border, fill, protection). Ctrl + F opens Find.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-60","question":"In MS Excel, how do you start a new line of text inside the same cell?","options":["Tab","Shift + Enter","Ctrl + Enter","Alt + Enter"],"answer":3,"explanation":"Alt + Enter inserts a line break within a cell. Shift + Enter moves to the cell above, and Ctrl + Enter enters the same data in all selected cells.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-61","question":"What does the Excel formula =ROUND(1234.567, -2) return?","options":["1200","1234.57","1234.6","1300"],"answer":0,"explanation":"A negative second argument rounds to the left of the decimal point: -2 rounds to the nearest hundred, giving 1200. 1234.57 would need 2 as the argument.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-62","question":"What does the Excel formula =MID(\"COMPUTER\", 3, 4) return?","options":["OMPU","MPUT","MPUTE","PUTE"],"answer":1,"explanation":"MID takes 4 characters starting at position 3: C(1) O(2) M(3) P(4) U(5) T(6) → MPUT.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-63","question":"In Excel, A1:A6 contain 45, 60, 75, 50, 90 and 30. What does =COUNTIF(A1:A6, \">50\") return?","options":["5","4","2","3"],"answer":3,"explanation":"Values strictly greater than 50 are 60, 75 and 90 → 3. The value 50 itself is not included; that would need \">=50\", which gives 4.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-64","question":"Which Excel 'What-If Analysis' tool finds the input value needed to make a formula reach a desired result?","options":["Data Validation","Scenario Manager","Goal Seek","Consolidate"],"answer":2,"explanation":"Goal Seek works backwards: you give the target result and the cell to change, and it finds the input. Scenario Manager compares several saved sets of inputs; Data Validation restricts entries.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-65","question":"The Excel feature that keeps the top row or first column visible while you scroll through a large sheet is:","options":["Freeze Panes","Split Cells","Wrap Text","Group"],"answer":0,"explanation":"View → Freeze Panes locks rows/columns in place. Wrap Text only fits text within a cell, and Group collapses rows or columns.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-66","question":"A PowerPoint file saved with the extension .ppsx:","options":["Contains macros","Is a PowerPoint template","Opens directly as a slide show when double-clicked","Can be opened only in PowerPoint 2003"],"answer":2,"explanation":".ppsx is a PowerPoint Show and opens straight into slide-show mode. A template is .potx, and a macro-enabled presentation is .pptm.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-67","question":"In PowerPoint, which feature lets you change the font, colours and logo of ALL slides in one place?","options":["Custom Slide Show","Slide Sorter","Rehearse Timings","Slide Master"],"answer":3,"explanation":"Editing the Slide Master changes every slide based on its layouts. Slide Sorter only reorders slides; Rehearse Timings records how long each slide is shown.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-68","question":"Which default port does the POP3 protocol use for downloading e-mail?","options":["143","110","25","993"],"answer":1,"explanation":"POP3 uses port 110. IMAP uses 143, SMTP uses 25 for sending, and 993 is IMAP over SSL/TLS.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-69","question":"An attacker redirects users who type a genuine bank's address to a fake look-alike site by corrupting DNS records. This attack is called:","options":["Spamming","Phishing","Pharming","Spoofing of caller ID"],"answer":2,"explanation":"Pharming poisons DNS or the hosts file so even a correctly typed address leads to the fake site. Phishing relies on luring the victim to click a link, usually in an e-mail.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-70","question":"A phishing attack aimed specifically at top executives such as a CEO or CFO is known as:","options":["Baiting","Vishing","Smishing","Whaling"],"answer":3,"explanation":"Whaling targets 'big fish' — senior executives. Vishing uses voice calls and smishing uses SMS; baiting leaves infected devices or tempting downloads for victims.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-71","question":"Malicious code planted in a program that stays dormant and activates only when a particular condition is met (such as a specific date) is a:","options":["Logic bomb","Worm","Adware","Botnet"],"answer":0,"explanation":"A logic bomb is triggered by a condition or date. A worm spreads by itself across networks, and a botnet is a network of compromised computers controlled remotely.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-72","question":"Under the Information Technology Act, 2000, identity theft — fraudulently using another person's password, electronic signature or other unique identification — is punishable under:","options":["Section 66A","Section 66C","Section 67","Section 43A"],"answer":1,"explanation":"Section 66C deals with identity theft. Section 66A was struck down by the Supreme Court in 2015; Section 67 concerns obscene material, and 43A covers compensation for failure to protect data.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-73","question":"Charging a phone at an infected public USB charging port, which secretly steals data or installs malware, is called:","options":["Shoulder surfing","Juice jacking","Tailgating","Clickjacking"],"answer":1,"explanation":"Juice jacking abuses the data lines of a USB port. Shoulder surfing is watching someone type a PIN, tailgating is following an authorised person through a secure door, and clickjacking tricks users into clicking hidden page elements.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-74","question":"What does the Excel formula =-2^2 return?","options":["4","-4","0","#VALUE!"],"answer":0,"explanation":"In Excel, negation has higher precedence than exponentiation, so it is evaluated as (-2)^2 = 4. In ordinary algebra (and in many programming languages) -2² would be -4, which is the trap.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-75","question":"What does the Excel formula =2^3^2 return?","options":["36","512","12","64"],"answer":3,"explanation":"Excel evaluates operators of equal precedence from left to right: (2^3)^2 = 8^2 = 64. Mathematical convention (right-to-left) would give 2^9 = 512.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-76","question":"What does the Excel formula =MOD(-7, 3) return?","options":["1","-1","2","-2"],"answer":2,"explanation":"Excel's MOD returns a result with the same sign as the divisor: MOD(n, d) = n − d × INT(n/d) = −7 − 3 × (−3) = 2. -1 is what truncating division (as in C or Java's %) gives.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-77","question":"What does the Excel formula =TRUNC(-4.7) return?","options":["-4.7","-5","-4","4"],"answer":2,"explanation":"TRUNC simply removes the decimal part, giving -4. INT rounds down to the next lower integer, so INT(-4.7) would be -5 — the tempting choice.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-78","question":"What does the Excel formula =ROUNDUP(-3.21, 1) return?","options":["-3.3","-3.2","-3.21","-4"],"answer":0,"explanation":"ROUNDUP always rounds away from zero, so -3.21 becomes -3.3. Rounding 'up' towards the larger value -3.2 is the trap.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-79","question":"What does the Excel formula =LEN(TRIM(\"  Data   Entry  \")) return?","options":["9","16","12","10"],"answer":3,"explanation":"TRIM removes leading and trailing spaces and reduces internal runs of spaces to a single space, leaving \"Data Entry\" — 10 characters including the one space.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-80","question":"What does the Excel formula =10-2^2*3 return?","options":["24","-2","192","4"],"answer":1,"explanation":"Order: exponent first (2^2 = 4), then multiplication (4 × 3 = 12), then subtraction (10 − 12 = −2). Working left to right without precedence gives 192.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-81","question":"In Excel, A1:A6 contain 45, 60, 75, 50, 90 and 30. What does =SUMIF(A1:A6, \">=50\") return?","options":["225","275","320","350"],"answer":1,"explanation":"Values ≥ 50 are 60, 75, 50 and 90; their sum is 275. Excluding 50 (i.e. \">50\") gives 225.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-82","question":"In Excel, A1:A6 contain 45, 60, 75, 50, 90 and 30. What does =AVERAGEIF(A1:A6, \">40\") return?","options":["75","58.33","64","53.33"],"answer":2,"explanation":"Values greater than 40: 45, 60, 75, 50, 90 → sum 320 ÷ 5 = 64. 58.33 is the plain average of all six values (350 ÷ 6).","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-83","question":"In Excel, A1:A4 contain 0, 40, 60, 80 and B1:B4 contain the grades F, C, B, A. What does =VLOOKUP(73, A1:B4, 2, TRUE) return?","options":["#N/A","A","C","B"],"answer":3,"explanation":"With TRUE (approximate match) VLOOKUP finds the largest value ≤ 73 in the sorted first column, which is 60, and returns its grade B. #N/A would come only with an exact match (FALSE).","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-84","question":"What does the Excel formula =MATCH(25, {10,20,30,40}, 1) return?","options":["2","3","#N/A","25"],"answer":0,"explanation":"Match type 1 returns the position of the largest value less than or equal to 25 in an ascending list — 20, at position 2. MATCH returns a position, not the value.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-85","question":"What does the Excel formula =LARGE({12,45,7,45,30}, 2) return?","options":["45","30","12","7"],"answer":0,"explanation":"LARGE counts duplicates separately: sorted descending the list is 45, 45, 30, 12, 7, so the 2nd largest is 45. Choosing 30 assumes duplicates are ignored.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-86","question":"What does the Excel formula =SUMPRODUCT({2,3,1}, {4,5,6}) return?","options":["120","21","29","15"],"answer":2,"explanation":"SUMPRODUCT multiplies corresponding items and adds: 2×4 + 3×5 + 1×6 = 8 + 15 + 6 = 29. 21 is simply the total of all six numbers.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-87","question":"In Excel, A1 contains the date 01-01-2024 and B1 contains 01-03-2024 (1 March 2024). What does =B1-A1 return?","options":["59","60","2","61"],"answer":1,"explanation":"Excel stores dates as serial numbers, so subtraction gives the days between them: 31 (January) + 29 (February in the leap year 2024) = 60. 59 assumes a 28-day February.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-88","question":"The Excel formula =A1+$B$1 is in cell C1. If it is copied to cell D3, it becomes:","options":["=A3+$B$1","=A1+$B$1","=B3+$C$3","=B3+$B$1"],"answer":3,"explanation":"The relative part shifts one column right and two rows down (A1 → B3); the absolute reference $B$1 does not change.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-89","question":"In Excel, pressing F4 repeatedly while the cursor is on the reference A1 in a formula cycles it through which sequence?","options":["A$1 → $A1 → $A$1 → A1","$A$1 → A$1 → $A1 → A1","$A1 → A$1 → $A$1 → A1","$A$1 → $A1 → A$1 → A1"],"answer":1,"explanation":"F4 first makes the reference fully absolute ($A$1), then locks only the row (A$1), then only the column ($A1), and finally returns to relative (A1).","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-90","question":"In Excel 2007 and later, how many rows and columns does a worksheet have?","options":["1,048,576 rows and 16,384 columns","65,536 rows and 256 columns","1,048,576 rows and 256 columns","16,384 rows and 1,048,576 columns"],"answer":0,"explanation":"Since Excel 2007 a sheet has 2²⁰ = 1,048,576 rows and 2¹⁴ = 16,384 columns (A to XFD). 65,536 × 256 was the limit in Excel 2003 and earlier.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-91","question":"Which Excel error value appears when a formula refers to a cell that has been deleted?","options":["#N/A","#NAME?","#REF!","#NULL!"],"answer":2,"explanation":"#REF! signals an invalid cell reference, typically after deleting rows, columns or cells used by a formula. #NAME? means Excel does not recognise a name or function.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-92","question":"In Excel, typing =SUMM(A1:A5) by mistake produces which error?","options":["#N/A","#VALUE!","#REF!","#NAME?"],"answer":3,"explanation":"Excel does not recognise the function name SUMM, so it shows #NAME?. #VALUE! arises from a wrong type of argument, such as adding text to a number.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-93","question":"In Excel, the shortcut Ctrl + ` (grave accent) is used to:","options":["Copy the value from the cell above","Insert the current time","Toggle between showing formulas and showing their results","Open the Visual Basic editor"],"answer":2,"explanation":"Ctrl + ` switches the sheet to formula view and back. Ctrl + Shift + ; inserts the time, Ctrl + ' copies the formula from the cell above, and Alt + F11 opens the VBA editor.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-94","question":"In Excel, pressing F11 with data selected:","options":["Recalculates all formulas","Inserts a new worksheet","Creates an embedded chart on the same sheet","Creates a default chart on a new chart sheet"],"answer":3,"explanation":"F11 makes a chart on a separate chart sheet; Alt + F1 makes an embedded chart on the current sheet. Shift + F11 inserts a new worksheet and F9 recalculates.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-95","question":"In Excel 2013 and later, which shortcut runs Flash Fill to complete a column based on a pattern you have typed?","options":["Ctrl + F","Ctrl + E","Ctrl + R","Ctrl + Shift + E"],"answer":1,"explanation":"Ctrl + E triggers Flash Fill. Ctrl + R fills right (copies the cell on the left), and Ctrl + F opens Find.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-96","question":"In MS Word, which shortcut inserts a footnote at the cursor position?","options":["Ctrl + Alt + F","Ctrl + Alt + D","Ctrl + Alt + M","Ctrl + Shift + F"],"answer":0,"explanation":"Ctrl + Alt + F inserts a footnote and Ctrl + Alt + D an endnote. Ctrl + Alt + M inserts a comment.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-97","question":"In MS Word, Ctrl + Shift + C followed by Ctrl + Shift + V on other text is used to:","options":["Count characters and paste the count","Copy and paste text without formatting","Insert a copyright symbol","Copy and paste only the formatting, like Format Painter"],"answer":3,"explanation":"Ctrl + Shift + C copies formatting and Ctrl + Shift + V applies it — the keyboard version of Format Painter. It does not copy the text itself.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-98","question":"In MS Word, which shortcut turns Track Changes on or off?","options":["Ctrl + Shift + E","Ctrl + Shift + T","Ctrl + Alt + T","Ctrl + T"],"answer":0,"explanation":"Ctrl + Shift + E toggles Track Changes. Ctrl + T creates a hanging indent and Ctrl + Shift + T removes it.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-99","question":"In MS Word, Ctrl + Backspace deletes:","options":["The whole current line","The word to the left of the cursor","The character to the right of the cursor","The whole paragraph"],"answer":1,"explanation":"Ctrl + Backspace deletes the previous word and Ctrl + Delete the next word. Plain Delete removes one character to the right.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-100","question":"In MS Word, the 'gutter' margin is:","options":["The space reserved for headers and footers","The space between two columns of text","Extra space added to a margin to allow for binding","The blank area at the end of the last page"],"answer":2,"explanation":"A gutter adds space to the side or top margin so text is not hidden by binding. The space between columns is simply the column spacing.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-101","question":"The Word paragraph option 'Widow/Orphan control' prevents:","options":["A single line of a paragraph being left alone at the top or bottom of a page","Text from wrapping around pictures","Hyphenation of long words","Headings from appearing in the table of contents"],"answer":0,"explanation":"With widow/orphan control on, Word will not leave the last line of a paragraph alone at the top of a page (widow) or its first line alone at the bottom (orphan).","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-102","question":"A Word document that contains macros must be saved with which extension to keep them?","options":[".dotx",".docx",".docm",".rtf"],"answer":2,"explanation":".docm is the macro-enabled document format. .docx cannot store macros, .dotx is a macro-free template and .rtf is Rich Text Format.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-103","question":"In a URL such as https://shop.example.com/items/list.html?page=2#reviews, the part 'page=2' is the:","options":["Fragment","Query string","Path","Host name"],"answer":1,"explanation":"Everything after '?' is the query string (here page=2). '#reviews' is the fragment, '/items/list.html' is the path, and shop.example.com is the host name.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-104","question":"Which protocol finds the MAC (hardware) address of a device on a local network when its IP address is known?","options":["ICMP","DHCP","DNS","ARP"],"answer":3,"explanation":"ARP (Address Resolution Protocol) maps an IPv4 address to a MAC address. DNS maps domain names to IP addresses and DHCP assigns IP addresses; ICMP carries error messages such as ping.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-105","question":"Which technology lets many devices on a home network with private IP addresses share a single public IP address on the internet?","options":["NAT (Network Address Translation)","DNS","FTP","VLAN"],"answer":0,"explanation":"NAT on the router rewrites private source addresses to its one public address and tracks the replies. DNS only resolves names to addresses.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-106","question":"In a Google search, which query restricts results to PDF documents from Indian government websites about 'digital literacy'?","options":["digital literacy site:pdf filetype:gov.in","digital literacy +pdf -gov.in","\"digital literacy\" OR pdf OR gov.in","digital literacy filetype:pdf site:gov.in"],"answer":3,"explanation":"filetype: limits the file format and site: limits the domain. The last option swaps the two operators, and '-gov.in' would exclude government sites.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-107","question":"Which part of the CIA triad of information security is the main target of a Distributed Denial-of-Service (DDoS) attack?","options":["Confidentiality","Availability","Integrity","Authenticity"],"answer":1,"explanation":"A DDoS floods a server with traffic so that legitimate users cannot reach it — an attack on availability. It does not usually steal (confidentiality) or alter (integrity) data.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-108","question":"An attacker types ' OR '1'='1 into a website's login box to bypass the password check. This is an example of:","options":["Brute-force attack","Cross-site scripting","SQL injection","Buffer overflow"],"answer":2,"explanation":"Inserting SQL code into an input field to alter the database query is SQL injection. Cross-site scripting injects scripts into web pages viewed by other users; brute force tries many passwords.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-109","question":"A network of computers infected with malware and controlled remotely by an attacker, often used to send spam or launch DDoS attacks, is called a:","options":["Honeypot","Botnet","Intranet","Firewall"],"answer":1,"explanation":"Each infected machine is a 'bot' or 'zombie'; together they form a botnet. A honeypot is a decoy system set up by defenders to attract attackers.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-110","question":"A security flaw that is exploited by attackers before the software vendor has released any fix for it is called a:","options":["Zero-day vulnerability","Backdoor","Patch","False positive"],"answer":0,"explanation":"'Zero-day' means the vendor has had zero days to fix it. A patch is the fix itself; a backdoor is a hidden way of bypassing authentication.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-111","question":"Which of these encryption algorithms is asymmetric, using a public key and a private key?","options":["Triple DES","AES","DES","RSA"],"answer":3,"explanation":"RSA is a public-key (asymmetric) algorithm. AES, DES and 3DES are symmetric: the same secret key encrypts and decrypts.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-112","question":"Which of the following pairs of factors gives genuine two-factor authentication?","options":["A PIN and a password","A password and a security question","A password and an OTP sent to the registered mobile","A fingerprint and a face scan"],"answer":2,"explanation":"Two-factor authentication needs factors of two different kinds — here something you know (password) and something you have (phone). Password + security question or PIN + password are both 'something you know'; fingerprint + face are both 'something you are'.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-113","question":"In Excel, the divisor is negative in =MOD(7, -3). What result does the formula give?","options":["1","-2","-1","2"],"answer":1,"explanation":"MOD(n, d) = n − d × INT(n/d) = 7 − (−3) × INT(−2.33) = 7 − (−3)(−3) = 7 − 9 = −2. The result takes the sign of the divisor, so the positive answers are traps.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-114","question":"What does the Excel formula =ROUNDDOWN(-3.78, 1) return?","options":["-4","-3.8","-3.7","-3.78"],"answer":2,"explanation":"ROUNDDOWN always rounds towards zero, so -3.78 becomes -3.7. 'Down' in the sense of a smaller number (-3.8) is the trap; FLOOR-style rounding would give that.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-115","question":"What does the Excel formula =ROUND(1250, -2) return?","options":["1300","1200","1250","1000"],"answer":0,"explanation":"Rounding to the nearest hundred, 1250 is exactly halfway; Excel's ROUND rounds halves away from zero, so the result is 1300. 1200 assumes 'round half to even' (banker's rounding), which Excel's ROUND does not use.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-116","question":"What does the Excel formula =-3^2+1 return?","options":["8","-8","-10","10"],"answer":3,"explanation":"Negation is applied before the exponent in Excel: (-3)^2 + 1 = 9 + 1 = 10. Treating it as -(3^2) + 1 gives -8, the algebra-textbook answer.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-117","question":"What does the Excel formula =\"A\"&1+2 return?","options":["A12","A3","#VALUE!","A1+2"],"answer":1,"explanation":"Arithmetic operators rank above the concatenation operator &, so 1+2 is worked out first and then joined: \"A\" & 3 = \"A3\". 'A12' would need brackets: =(\"A\"&1)&2.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-118","question":"What does the Excel formula =FIND(\"N\", \"Banana\") return?","options":["#N/A","3","0","#VALUE!"],"answer":3,"explanation":"FIND is case-sensitive, and \"Banana\" has no capital N, so it returns #VALUE!. SEARCH, which ignores case, would return 3.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-119","question":"What does the Excel formula =SEARCH(\"N\", \"Banana\") return?","options":["3","#VALUE!","5","2"],"answer":0,"explanation":"SEARCH is not case-sensitive, so it finds the first 'n' at position 3 (B-a-n). FIND would have failed with #VALUE! because it is case-sensitive.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-120","question":"In Excel, A1 = 5, A2 contains the TEXT \"7\" (entered as text), A3 = TRUE, A4 is blank and A5 = 3. What does =COUNT(A1:A5) return?","options":["4","3","2","5"],"answer":2,"explanation":"COUNT counts only numeric cells in a range: 5 and 3. Numbers stored as text and logical values inside a range are ignored, so 3 or 4 are traps; COUNTA would return 4.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-121","question":"In Excel, A1 = 5 and A2 contains the text \"7\" (a number stored as text). What do =SUM(A1:A2) and =A1+A2 return respectively?","options":["12 and 5","12 and 12","5 and #VALUE!","5 and 12"],"answer":3,"explanation":"SUM over a range ignores text, giving 5. But the + operator converts numeric text into a number, so =A1+A2 gives 12.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-122","question":"In Excel, A1:A4 contain 1, 2, 3 and 4. What does =SUM(A1:A3,A2:A4) return?","options":["10","15","5","9"],"answer":1,"explanation":"The comma is the union operator, so both ranges are added in full and the overlapping cells A2 and A3 count twice: (1+2+3) + (2+3+4) = 15. 10 assumes the overlap is counted once.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-123","question":"In Excel, A1:A4 contain 1, 2, 3 and 4. What does =SUM(A1:A3 A2:A4) return (note the space between the ranges)?","options":["10","15","5","#NULL!"],"answer":2,"explanation":"A space is Excel's intersection operator; the ranges overlap in A2:A3, so the result is 2 + 3 = 5. #NULL! would appear only if the ranges did not overlap at all.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-124","question":"Which Excel error value appears for =SUM(A1:A3 C1:C3)?","options":["#NULL!","#REF!","#VALUE!","#N/A"],"answer":0,"explanation":"The space between the ranges is the intersection operator, and A1:A3 and C1:C3 share no cell, so Excel returns #NULL!.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-125","question":"The formula =$A1*B$2 is in cell C3. When it is copied to cell E5, it becomes:","options":["=$A3*D$2","=$A1*D$2","=$C3*D$4","=$A3*B$4"],"answer":0,"explanation":"Moving two columns right and two rows down: in $A1 the column is locked and the row changes (1 → 3); in B$2 the row is locked and the column changes (B → D).","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-126","question":"What does the Excel formula =DATE(2024, 2, 30) return?","options":["2 March 2024","#NUM!","29 February 2024","1 March 2024"],"answer":3,"explanation":"DATE rolls extra days over into the next month. February 2024 has 29 days (leap year), so day 30 becomes 1 March 2024. 2 March would be correct for a non-leap year.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-127","question":"What does the Excel formula =DATE(2023, 13, 1) return?","options":["1 December 2023","#NUM!","1 January 2024","13 January 2023"],"answer":2,"explanation":"A month number above 12 rolls over into the next year: month 13 of 2023 is January 2024. Excel does not raise an error for it.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-128","question":"In Excel, the column immediately after column AZ is BA. What is the column number of AZ, and which column is number 100?","options":["52; CU","52; CV","51; CV","78; DV"],"answer":1,"explanation":"AZ = 1×26 + 26 = 52. For 100: 100 = 3×26 + 22, i.e. third letter C and 22nd letter V → CV.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-129","question":"In Excel, A1 = 75. What does =IF(A1>=40, IF(A1>=75, \"Distinction\", \"Pass\"), \"Fail\") return?","options":["FALSE","Pass","Fail","Distinction"],"answer":3,"explanation":"75 ≥ 40 is TRUE, so the inner IF runs; 75 ≥ 75 is also TRUE (the test is 'greater than or equal'), giving \"Distinction\". Reading >= as > leads to the trap \"Pass\".","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-130","question":"In Excel, A2:A5 contain the names Asha, Ravi, Meena, Tarun and B2:B5 contain 82, 67, 91, 74. What does =INDEX(B2:B5, MATCH(\"Meena\", A2:A5, 0)) return?","options":["67","3","91","Meena"],"answer":2,"explanation":"MATCH finds \"Meena\" at position 3 of A2:A5 (exact match, type 0), and INDEX returns the 3rd value of B2:B5, which is 91. 3 is only MATCH's output.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-131","question":"In Excel, A1 = 0.256. What does =TEXT(A1, \"0.0%\") return?","options":["0.3%","25.6%","26%","2.6%"],"answer":1,"explanation":"The % in the format code multiplies the value by 100 and adds a percent sign; \"0.0\" keeps one decimal place: 25.6%. Ignoring the multiplication gives 0.3%.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-132","question":"In Excel, what does =IFERROR(1/0, \"Check\") & \"!\" return?","options":["Check!","#DIV/0!","#DIV/0!!","Check"],"answer":0,"explanation":"1/0 is an error, so IFERROR returns \"Check\"; the & operator then joins \"!\" to give \"Check!\".","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-133","question":"Which of the following Excel formulas does NOT return an error?","options":["=\"5\"*2","=\"abc\"*2","=SQRT(-4)","=VLOOKUP(99,{1,\"a\";2,\"b\"},2,FALSE)"],"answer":0,"explanation":"\"5\"*2 converts the numeric text to 5 and returns 10. \"abc\"*2 gives #VALUE!, SQRT of a negative number gives #NUM!, and an exact-match VLOOKUP that finds nothing gives #N/A.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-134","question":"The same key combination does different things in different Office programs. What does Ctrl + D do in MS Word, MS Excel and MS PowerPoint respectively?","options":["Fills down; opens the Font dialog; deletes the slide","Opens the Font dialog; fills down; duplicates the selected slide or object","Duplicates; fills down; opens the Font dialog","Opens the Font dialog; deletes the row; duplicates the slide"],"answer":1,"explanation":"In Word, Ctrl + D opens the Font dialog; in Excel it copies the top cell of a selection down (Fill Down); in PowerPoint it duplicates the selected slide or object.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-135","question":"In MS Word, which pair of shortcuts increases and decreases the font size of the selected text by exactly 1 point?","options":["Alt + ] and Alt + [","Ctrl + Shift + > and Ctrl + Shift + <","Ctrl + + and Ctrl + -","Ctrl + ] and Ctrl + ["],"answer":3,"explanation":"Ctrl + ] and Ctrl + [ change the size by one point. Ctrl + Shift + > and < jump to the next or previous size in the font-size list (e.g. 12 → 14), which is the trap.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-136","question":"In MS Word, Shift + Enter, Ctrl + Enter and Ctrl + Shift + Enter insert, respectively:","options":["A column break, a page break and a line break","A page break, a line break and a section break","A line break, a page break and a column break","A paragraph break, a column break and a page break"],"answer":2,"explanation":"Shift + Enter = manual line break (same paragraph); Ctrl + Enter = page break; Ctrl + Shift + Enter = column break.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-137","question":"In MS Word, which type of section break should be used to change from one-column to two-column layout in the middle of a page, without starting a new page?","options":["Continuous","Next Page","Even Page","Odd Page"],"answer":0,"explanation":"A Continuous section break starts a new section on the same page, so the column layout can change mid-page. Next Page, Even Page and Odd Page breaks all force the new section onto another page.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-138","question":"In Word's Mail Merge, which statement is correct?","options":["Merge fields are typed manually as plain text between angle brackets","The data source must be another Word document; Excel lists cannot be used","The main document holds the fixed text and merge fields, while the data source supplies the values that change for each recipient","Mail Merge can only produce letters, not envelopes or labels"],"answer":2,"explanation":"The main document contains constant text plus merge fields; the data source (Excel sheet, Access table, Outlook contacts or a Word table) holds the variable data. Typing «Name» by hand does not create a working field, and Mail Merge can also make envelopes, labels and e-mails.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-139","question":"During a PowerPoint slide show, what happens when you type 7 and then press Enter?","options":["The show advances seven slides","The show jumps directly to slide 7","The pen colour changes","The screen zooms to 70%"],"answer":1,"explanation":"Typing a slide number and pressing Enter jumps straight to that slide. Ctrl + P switches the pointer to a pen during a show.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-140","question":"Which statement about PowerPoint transitions and animations is correct?","options":["Animations can be added only in Slide Master view","A transition applies to text boxes and an animation to whole slides","Both terms mean the same effect","A transition is an effect applied when moving from one slide to the next; an animation is applied to an object within a slide"],"answer":3,"explanation":"Transitions work between slides; animations make individual objects (text, pictures, charts) enter, exit or move. They are set from separate tabs.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-141","question":"Match the protocol with its default port: 1. Telnet 2. IMAP 3. POP3 over SSL (POP3S) 4. RDP; a. 3389 b. 995 c. 23 d. 143","options":["1-d, 2-c, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-c, 2-d, 3-a, 4-b"],"answer":2,"explanation":"Telnet uses 23, IMAP 143, POP3S 995 and Remote Desktop Protocol 3389. Note that IMAPS (993) and POP3S (995) are easily confused.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-142","question":"Ignoring overheads, roughly how long will it take to download a 1 GB file (1 GB = 1024 MB) on a 20 Mbps connection?","options":["About 6.8 minutes","About 51 seconds","About 3.4 minutes","About 54 minutes"],"answer":0,"explanation":"1 GB = 1024 MB × 8 = 8192 megabits; 8192 ÷ 20 = 409.6 seconds ≈ 6.8 minutes. 51 seconds forgets to convert bytes into bits.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-143","question":"Ravi wants to send a confidential file to Neha using public-key cryptography so that only Neha can read it. Which key should be used to encrypt the file?","options":["Neha's private key","Ravi's public key","Ravi's private key","Neha's public key"],"answer":3,"explanation":"For confidentiality, encrypt with the recipient's public key; only the recipient's private key can decrypt it. Encrypting with Ravi's private key is how a digital signature is made — it proves origin but anyone with Ravi's public key can read it.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-144","question":"To verify the digital signature on a document signed by a bank, the receiver uses:","options":["The bank's private key","The bank's public key","The receiver's private key","A shared secret password"],"answer":1,"explanation":"A signature is created with the signer's private key and verified with the signer's public key, usually obtained from a digital certificate issued by a Certifying Authority. The private key is never shared.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-145","question":"How many hexadecimal characters long is a SHA-256 hash value when written out?","options":["32","64","256","128"],"answer":1,"explanation":"SHA-256 produces a 256-bit digest; each hex character represents 4 bits, so 256 ÷ 4 = 64 characters. 32 hex characters is the length of an MD5 (128-bit) hash.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-146","question":"How many of these statements about HTTPS are correct? I. It uses TLS to encrypt data between browser and server. II. Its default port is 443. III. The padlock icon proves the website belongs to a trustworthy organisation. IV. It hides the website address from the user's internet service provider.","options":["Only two","Only three","Only one","All four"],"answer":0,"explanation":"I and II are correct. III is wrong — the padlock only shows an encrypted connection with a valid certificate; phishing sites can have one too. IV is wrong — the ISP can still see which domain is visited (through DNS and the TLS handshake), even if not the page content.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-147","question":"How many of these statements about browsing are correct? I. A private/incognito window does not save history or cookies after it is closed. II. Incognito mode hides your browsing from your employer's network. III. Third-party cookies are commonly used for cross-site ad tracking. IV. Clearing the browser cache removes saved copies of web pages and images.","options":["All four","Only two","Only three","Only one"],"answer":2,"explanation":"I, III and IV are correct. II is wrong: incognito mode only avoids storing data on the local device; the network administrator, ISP and the visited websites can still see the traffic.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-148","question":"Under the IT Act, 2000, which section prescribes punishment that may extend to imprisonment for life for cyber terrorism?","options":["Section 43","Section 66C","Section 66D","Section 66F"],"answer":3,"explanation":"Section 66F covers cyber terrorism, punishable with imprisonment up to life. 66C is identity theft and 66D cheating by personation using a computer resource; Section 43 provides compensation (a civil remedy), not imprisonment.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-149","question":"A fraudster convinces a mobile operator to issue a new SIM for a victim's number, then uses the OTPs received on it to empty the victim's bank account. This is known as:","options":["SIM swap fraud","Vishing","Juice jacking","Pharming"],"answer":0,"explanation":"In SIM swap (SIM cloning) fraud the criminal takes control of the victim's number, so bank OTPs reach him. Vishing is fraud by phone call and needs the victim to reveal details; juice jacking uses USB charging ports.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-150","question":"Assertion (A): A firewall alone cannot protect a user who opens a malicious e-mail attachment. Reason (R): A firewall filters network traffic by rules, but the attachment arrives through permitted e-mail traffic and runs on the user's machine.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A firewall allows e-mail traffic because it is legitimate; the malicious code runs only when the user opens it. That is exactly why A holds, so R explains A. Antivirus and user awareness are needed in addition.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-151","question":"What does the Excel formula =MROUND(17, 5) return?","options":["20","3","17","15"],"answer":3,"explanation":"MROUND rounds to the NEAREST multiple of 5. 17 is 2 away from 15 and 3 away from 20, so the result is 15. 3 is just how many times 5 fits into 17.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-152","question":"What does the Excel formula =CEILING(4.1, 2) + FLOOR(7.9, 2) return?","options":["12","14","10","11"],"answer":0,"explanation":"CEILING(4.1, 2) rounds up to the next multiple of 2, giving 6; FLOOR(7.9, 2) rounds down to a multiple of 2, giving 6; so 6 + 6 = 12. Rounding 7.9 up to 8 gives 14, rounding 4.1 down to 4 gives 10, and treating CEILING as a plain round-up to a whole number (5) gives 11.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-153","question":"In Excel, A1 = 10, A2 is empty, A3 = 0 and A4 = 20. What does =AVERAGE(A1:A4) return?","options":["7.5","15","10","#DIV/0!"],"answer":2,"explanation":"AVERAGE ignores empty cells but counts a 0 as a value, so it gives (10 + 0 + 20) ÷ 3 = 10. 7.5 treats the blank as 0; 15 ignores the zero as well.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-154","question":"In Excel, A1 = 5, A2 = Yes, A3 is empty, A4 holds the formula =\"\", A5 = 0 and A6 is empty. What do =COUNTA(A1:A6) and =COUNTBLANK(A1:A6) return?","options":["3 and 3","4 and 2","3 and 2","4 and 3"],"answer":3,"explanation":"COUNTA counts every non-empty cell, and A4 contains a formula, so 5, Yes, the formula and 0 make 4. COUNTBLANK counts truly empty cells AND cells showing empty text, so A3, A4 and A6 make 3; a 0 is not blank.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-155","question":"What does the Excel formula =SUBSTITUTE(\"banana\", \"a\", \"o\", 2) return?","options":["bonono","banona","bonana","banano"],"answer":1,"explanation":"The fourth argument tells SUBSTITUTE to change only the 2nd occurrence of 'a', which is the one after 'ban', giving banona. Without that argument every 'a' would change (bonono).","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-156","question":"What does the Excel formula =REPLACE(\"ABCDEF\", 2, 3, \"x\") return?","options":["AxCDEF","AxDEF","ABxEF","AxEF"],"answer":3,"explanation":"REPLACE removes 3 characters starting at position 2 (B, C, D) and puts 'x' in their place: A + x + EF = AxEF. It works by position, unlike SUBSTITUTE, which works by matching text.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-157","question":"A user types =1+1=2 into an Excel cell. What does the cell show?","options":["TRUE","2","FALSE","#VALUE!"],"answer":0,"explanation":"The first = starts the formula; arithmetic is done before comparison, so 1+1 gives 2 and then 2=2 is tested, which gives TRUE.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-158","question":"1 January 2024 was a Monday. What does =WEEKDAY(DATE(2024, 1, 1)) return in Excel?","options":["1","2","0","7"],"answer":1,"explanation":"With no second argument, WEEKDAY numbers the days from Sunday = 1 to Saturday = 7, so Monday is 2. Getting 1 assumes the week starts on Monday.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-159","question":"What date does the Excel formula =EDATE(DATE(2024, 1, 31), 1) return?","options":["2 March 2024","28 February 2024","29 February 2024","#VALUE!, because 31 February does not exist"],"answer":2,"explanation":"EDATE moves the date by whole months and, when the day does not exist, uses the last day of the target month. February 2024 has 29 days (leap year), so the result is 29 February 2024. DATE(2024,2,31) would roll over to 2 March instead.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-160","question":"What date does the Excel formula =EOMONTH(DATE(2023, 2, 10), 0) return?","options":["31 January 2023","28 February 2023","29 February 2023","31 March 2023"],"answer":1,"explanation":"EOMONTH gives the last day of the month that is the given number of months away; 0 means the same month, February 2023, whose last day is the 28th because 2023 is not a leap year. An offset of −1 would give 31 January.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-161","question":"A cell contains the number 0.75 and is then formatted as a time. What does it show?","options":["7:30 AM","9:00 AM","6:00 PM","7:50 PM"],"answer":2,"explanation":"Excel stores a time as a fraction of a 24-hour day: 0.75 × 24 = 18 hours, i.e. 6:00 PM. 7:30 reads the decimal digits as hours and minutes.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-162","question":"Column A holds regions and column C holds sales for rows 2 to 10. Which formula correctly totals the sales of the 'North' region?","options":["=SUMIF(C2:C10, \"North\", A2:A10)","=SUMIFS(A2:A10, \"North\", C2:C10)","=SUMIFS(C2:C10, \"North\", A2:A10)","=SUMIF(A2:A10, \"North\", C2:C10)"],"answer":3,"explanation":"SUMIF takes (criteria range, criteria, sum range). SUMIFS puts the sum range FIRST and then pairs of (criteria range, criteria), so a correct SUMIFS would be =SUMIFS(C2:C10, A2:A10, \"North\"); both SUMIFS options given break that order.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-163","question":"The lookup value 'X' does exist in the first column of A1:C10. What does =VLOOKUP(\"X\", A1:C10, 4, FALSE) return?","options":["#N/A","The value in column D of the matching row","#REF!","#VALUE!"],"answer":2,"explanation":"The table A1:C10 has only 3 columns, so asking for column 4 points outside it and gives #REF!. #N/A appears only when the lookup value cannot be found.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-164","question":"Match each Excel formula with the error it gives: 1. =10/0 2. =\"abc\"*2 3. =SQRT(-1) 4. =MATCH(\"Z\", {\"A\",\"B\"}, 0); a. #NUM! b. #N/A c. #DIV/0! d. #VALUE!","options":["1-c, 2-d, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a"],"answer":0,"explanation":"Division by zero gives #DIV/0!, arithmetic on text gives #VALUE!, an impossible numeric result such as the square root of a negative gives #NUM!, and an exact match that is not found gives #N/A.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-165","question":"In Excel, A1 = 2 and A2 = 5. Both cells are selected and the fill handle is dragged down to A5. What value appears in A5?","options":["11","5","14","17"],"answer":2,"explanation":"With two cells selected, Excel continues their step (+3): 2, 5, 8, 11, 14, so A5 = 14. 5 would appear only if a single cell were copied down.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-166","question":"In Excel, A1 contains the text 'Jan'. Its fill handle is dragged down to A14. What does A14 contain?","options":["Jan","Mar","Dec","Feb"],"answer":3,"explanation":"Excel recognises month names as a built-in list and repeats it: A1–A12 run Jan to Dec, A13 is Jan again and A14 is Feb.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-167","question":"A workbook has sheets named Jan, Feb, Mar and Apr in that tab order. What does =SUM(Jan:Mar!B5) add up?","options":["Cell B5 on the Jan, Feb and Mar sheets","Cells B5 on the Jan and Mar sheets only","All cells from Jan!A1 to Mar!B5","Cell B5 on every sheet in the workbook"],"answer":0,"explanation":"Jan:Mar!B5 is a 3-D reference: the same cell, B5, on every sheet from Jan to Mar in tab order, including Feb in between. Apr lies outside the range.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-168","question":"In an Excel sheet, what does the shortcut Ctrl + End do?","options":["Moves to the last cell of the used range: the last used row and last used column","Moves to cell A1","Moves to row 1,048,576 of the current column","Moves to the end of the text inside the current cell"],"answer":0,"explanation":"Ctrl + End jumps to the bottom-right corner of the area that has ever held data; Ctrl + Home goes back to A1. Editing within a cell uses End on its own.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-169","question":"A user types '123 (with a leading apostrophe) into an Excel cell. What happens?","options":["The cell shows '123 and is treated as a formula","123 is stored as text and is left-aligned by default","123 is stored as a number and is right-aligned","Excel shows a #VALUE! error"],"answer":1,"explanation":"A leading apostrophe makes Excel store the entry as text; the apostrophe is hidden, and text is left-aligned by default while numbers align to the right.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-170","question":"In Excel's standard (1900) date system, a cell containing the number 45 is formatted as a date. Which date does it show?","options":["45 days after today","15 February 1900","14 February 1900","1 January 1945"],"answer":2,"explanation":"Dates are serial numbers with 1 = 1 January 1900. Serial 31 is 31 January, so serial 45 is 14 days into February: 14 February 1900. 15 February is the off-by-one trap of counting from serial 0.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-171","question":"What does the Excel formula =INT(-3.5) return?","options":["−3","−4","−3.5","#NUM!, because INT needs a positive number"],"answer":1,"explanation":"INT rounds DOWN to the next smaller integer, and for negatives that means away from zero: −3.5 becomes −4. TRUNC(−3.5) would just cut off the decimal and give −3; INT accepts negative numbers.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-172","question":"What does the Excel formula =ROUND(-2.5, 0) return?","options":["−2","−2.5","−3","#NUM!"],"answer":2,"explanation":"Excel's ROUND sends an exact half away from zero, so −2.5 becomes −3. −2 is the trap from 'round half to even' (banker's rounding), which ROUND does not use; negative numbers are allowed.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-173","question":"What does the Excel formula =EVEN(-3) + ODD(4) return?","options":["3","1","9","#NUM!"],"answer":1,"explanation":"EVEN and ODD round AWAY from zero: EVEN(−3) = −4 and ODD(4) = 5, so the sum is 1. Rounding −3 towards zero to −2 gives the trap 3; both functions accept negative numbers.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-174","question":"What does the Excel formula =EXACT(PROPER(\"rAM kUMAR\"), \"Ram Kumar\") return?","options":["FALSE","Ram Kumar","TRUE","#VALUE!"],"answer":2,"explanation":"PROPER turns 'rAM kUMAR' into 'Ram Kumar' (first letter of each word capital, the rest small). EXACT is case-sensitive and returns TRUE because the two texts now match exactly.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-175","question":"A commission rate is stored in F1. The formula =B2*F1 must be copied both down the column and across to other columns, always using F1. How should F1 be written?","options":["Row locked only: F$1","Column locked only: $F1","Fully relative: F1","Fully absolute: $F$1"],"answer":3,"explanation":"Copying down changes the row and copying across changes the column, so both must be locked: $F$1. F$1 locks only the row and would drift to G1, H1 when copied across.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-176","question":"In MS Word, which shortcut formats the selected text as superscript, as for the '2' in x²?","options":["Ctrl + Shift + =","Ctrl + =","Ctrl + Shift + S","Alt + Shift + ="],"answer":0,"explanation":"Ctrl + Shift + = (Ctrl + plus) makes superscript, while Ctrl + = makes subscript, as in H₂O. Pressing the same shortcut again removes the formatting.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-177","question":"In MS Word, the text 'Rbi Policy' is selected and the All Caps format (Ctrl + Shift + A) is applied. What happens?","options":["The letters are permanently retyped as capitals, like using Caps Lock","It shows as RBI POLICY, but the stored text is unchanged, so removing the format brings back 'Rbi Policy'","The text changes to small capitals","Each press cycles the case through lower, UPPER and Title Case"],"answer":1,"explanation":"All Caps is a character FORMAT: the display changes but the typed letters stay as they were. Shift + F3 is the command that actually changes the case and cycles through the options.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-178","question":"In MS Word, which shortcut removes the manual paragraph formatting of a paragraph (such as extra indents and spacing) while leaving its bold and italic character formatting untouched?","options":["Ctrl + Space","Ctrl + E","Ctrl + Z","Ctrl + Q"],"answer":3,"explanation":"Ctrl + Q resets direct paragraph formatting; Ctrl + Space resets direct CHARACTER formatting such as bold and italic. Ctrl + E centres the paragraph, and Ctrl + Z undoes only the last action.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-179","question":"What does the shortcut Ctrl + T do to the current paragraph in MS Word?","options":["Creates a hanging indent","Inserts a table","Opens the Tabs dialog box","Turns Track Changes on"],"answer":0,"explanation":"In Word, Ctrl + T gives a hanging indent (all lines except the first move in); Ctrl + M indents the whole paragraph. The trap is Excel, where Ctrl + T turns a range into a table.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-180","question":"In a Word document, '₹ 500' keeps splitting so that '₹' ends one line and '500' starts the next. Which shortcut should be used in place of the ordinary space to keep them together?","options":["Shift + Enter","Ctrl + Space","Ctrl + Shift + Space","Ctrl + Enter"],"answer":2,"explanation":"Ctrl + Shift + Space inserts a non-breaking space, which Word never breaks across lines. Shift + Enter forces a line break, Ctrl + Space clears character formatting, and Ctrl + Enter inserts a page break.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-181","question":"A user wants to copy the formatting of one heading onto several other headings scattered through a long Word document. What is the quickest way with Format Painter?","options":["Double-click Format Painter so it stays on, click each heading, then press Esc","Single-click Format Painter once and it stays on until the document is closed","Single-click Format Painter separately before each heading; double-clicking does nothing","Select all the headings first and then click Format Painter"],"answer":0,"explanation":"A single click applies the formatting once and then switches off; a double click locks Format Painter on for repeated use until Esc is pressed or the button is clicked again.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-182","question":"Word's automatic Table of Contents picks up its entries mainly from:","options":["All text formatted in bold","Paragraphs formatted with the built-in Heading styles","Bookmarks inserted in the document","Any text whose font size is larger than 14 points"],"answer":1,"explanation":"The automatic TOC is built from Heading 1, Heading 2 and similar styles (outline levels), so headings that only LOOK big and bold but use no heading style are missed.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-183","question":"In MS Word, what does the shortcut Alt + Ctrl + D do?","options":["Inserts a footnote at the bottom of the current page","Inserts the current date as a field","Inserts an endnote at the end of the document","Duplicates the current paragraph"],"answer":2,"explanation":"Alt + Ctrl + D inserts an endnote, collected at the end of the document (or section); Alt + Ctrl + F inserts a footnote at the bottom of the page, and Alt + Shift + D inserts the date.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-184","question":"A report's cover page must show no header, while every other page shows the bank's name in the header. Which Word option does this without section breaks?","options":["Delete the header text on page 1 only","Different Odd and Even Pages","Link to Previous","Different First Page"],"answer":3,"explanation":"'Different First Page' gives the first page of the section its own (here, empty) header. Deleting the header on page 1 would delete it everywhere, because all pages share it.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-185","question":"A portrait Word report must show one wide table on a single landscape page in the middle, with all other pages staying portrait. What is the correct method?","options":["Put a Next Page section break before and after the table, then set only that section to Landscape","Put page breaks (Ctrl + Enter) before and after the table, then set Landscape","Put column breaks around the table, then set Landscape","Select the table and set Landscape with 'Apply to: Whole document'"],"answer":0,"explanation":"Orientation is a section property, so the table needs its own section starting on a new page. Page and column breaks do not create sections, so changing orientation would affect the whole document.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-186","question":"Typing 'teh' followed by a space in Word turns it into 'the' at once. Which feature does this?","options":["Spell check (F7)","AutoCorrect","Thesaurus","Find and Replace"],"answer":1,"explanation":"AutoCorrect replaces entries from its list as you type. Spell check only underlines or suggests corrections; it does not change words as you type.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-187","question":"A Word document contains the sentence: 'The bank and the Bank of Baroda are near the banking hub.' Find is run for bank with both 'Match case' and 'Find whole words only' switched on. How many matches are found?","options":["1","2","3","0"],"answer":0,"explanation":"Match case rules out 'Bank', and whole words only rules out 'banking', leaving just the lower-case word 'bank'. With neither option on, all three would match.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-188","question":"A letter must keep basic formatting such as bold, fonts and alignment, and still open in almost any word processor, not only in MS Word. Which format suits this best?","options":[".txt",".docm",".rtf",".dotx"],"answer":2,"explanation":"Rich Text Format (.rtf) stores basic formatting in a widely supported form. .txt keeps no formatting, .docm is a macro-enabled Word document and .dotx is a Word template.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-189","question":"In MS Word, F7 starts the spelling and grammar check. What does Shift + F7 open?","options":["Word count","The Thesaurus, which suggests synonyms","The Translate tool","The Find and Replace box"],"answer":1,"explanation":"Shift + F7 opens the Thesaurus for the selected word. Word count is Ctrl + Shift + G, and Find and Replace is Ctrl + H.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-190","question":"With Word's Show/Hide ¶ button switched on, which marks represent a space and a tab character?","options":["A pilcrow (¶) for a space and a raised dot (·) for a tab","A right arrow (→) for a space and a pilcrow (¶) for a tab","A degree sign (°) for a space and a return arrow (↵) for a tab","A raised dot (·) for a space and a right arrow (→) for a tab"],"answer":3,"explanation":"Show/Hide displays non-printing characters: a raised dot for each space, an arrow for each tab and ¶ at the end of each paragraph. These marks never print.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-191","question":"During a PowerPoint slide show, what does pressing W (or the comma key) do?","options":["Turns the screen white until another key is pressed","Turns the screen black until another key is pressed","Switches the pointer to a pen","Ends the slide show"],"answer":0,"explanation":"W or comma blanks the screen to white, while B or full stop blanks it to black; pressing the key again returns to the slide. Esc ends the show.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-192","question":"In PowerPoint, an object already on the slide must spin or pulse to draw attention, without entering or leaving the slide. Which type of animation is this?","options":["Entrance","Exit","Emphasis","Motion path"],"answer":2,"explanation":"Emphasis effects act on an object that is already visible. Entrance brings it on, exit takes it off, and a motion path moves it along a drawn route.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-193","question":"A PowerPoint show is set up as 'Browsed at a kiosk (full screen)' for a branch lobby display. Which statement about it is correct?","options":["Each slide advances only when a visitor clicks the mouse","It plays once and then returns to Normal view","It works only in Presenter View on two monitors","It loops continuously until Esc is pressed, and mouse clicks do not advance slides, so timings must be set"],"answer":3,"explanation":"Kiosk mode loops automatically and ignores clicks for advancing (only hyperlinks and action buttons work), so slide timings or buttons are needed or the show stays on one slide.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-194","question":"When printing PowerPoint handouts, which 'slides per page' layout also prints ruled lines beside each slide for the audience to take notes?","options":["1 slide","3 slides","6 slides","9 slides"],"answer":1,"explanation":"Only the 3-slides-per-page handout layout places lines for notes next to each slide. The other layouts simply fit more or fewer thumbnails on the page.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-195","question":"A slide in a PowerPoint presentation is marked as 'Hide Slide'. Which statement is correct?","options":["It is skipped during the slide show but stays in the file and can still be reached through a hyperlink","It is permanently deleted when the file is saved","It is shown during the slide show but not printed","It appears only in Slide Sorter view and can never be shown"],"answer":0,"explanation":"Hiding a slide only skips it in the normal flow of the show; it is still saved and editable, and a hyperlink or action button can jump to it.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-196","question":"In PowerPoint's Presenter View with two screens, what does the audience see compared with the presenter?","options":["Both see the speaker notes","The audience sees only the current slide, while the presenter also sees the notes, the next slide and a timer","The audience sees all slides as thumbnails","The presenter sees only the slide, while the audience sees the notes"],"answer":1,"explanation":"Presenter View keeps notes, the upcoming slide and timing tools on the presenter's screen; the projector shows only the slide itself.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-197","question":"Which PowerPoint feature lets you run through a presentation while it records how long each slide stays on screen, so that it can later advance automatically?","options":["Rehearse Timings","Record Macro","Slide Master","Custom Slide Show"],"answer":0,"explanation":"Rehearse Timings stores the time spent on each slide and can use it for automatic advancing. A custom show is just a chosen subset of slides.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-198","question":"In PowerPoint, the title font is changed on the Slide MASTER (the top thumbnail), and the background is changed on just ONE of the layouts below it. What is the result?","options":["Both changes apply only to the slide currently open","Both changes apply to every slide in the presentation","The font changes on all slides, but the background changes only on slides using that layout","The background changes on all slides, but the font changes only on slides using that layout"],"answer":2,"explanation":"Changes on the master pass down to every layout and so to all slides; a change on a single layout affects only the slides built on that layout.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-199","question":"In PowerPoint, which tool copies the animation effects of one object and applies them to another object in a single step?","options":["Format Painter","Slide Master","Paste Special","Animation Painter"],"answer":3,"explanation":"Animation Painter copies animation settings (effect, timing, duration) just as Format Painter copies formatting. Format Painter does not carry animations.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-200","question":"In PowerPoint, a picture should appear only when the presenter clicks a particular button-shaped shape, not on any ordinary click of the slide. Which animation setting does this?","options":["Start: After Previous","Start: With Previous","Loop until next click","A trigger set to 'On click of' that shape"],"answer":3,"explanation":"A trigger links the animation to a click on a chosen object, so it runs only when that object is clicked. After/With Previous start effects automatically in the normal sequence.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-201","question":"Asha e-mails a circular To: Ravi, Cc: Meena and Bcc: Tarun. Meena clicks 'Reply All'. Who receives Meena's reply?","options":["Asha and Ravi","Asha, Ravi and Tarun","Only Asha","Ravi and Tarun"],"answer":0,"explanation":"Bcc addresses are hidden from the other recipients, so Meena's mail program does not know Tarun was included; Reply All goes to the sender (Asha) and the visible To/Cc recipients (Ravi).","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-202","question":"You receive an e-mail with a PDF attached. What normally happens to the attachment when you click Reply and when you click Forward?","options":["Both Reply and Forward include it","Reply leaves it out; Forward includes it","Reply includes it; Forward leaves it out","Neither includes it unless it is attached again"],"answer":1,"explanation":"Replying goes back to someone who already has the file, so attachments are dropped; forwarding sends the message to someone new, so attachments are kept.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-203","question":"An officer reads office mail on both a phone and a laptop and wants read/unread status and folders to stay the same on both, with the mail kept on the server. Which protocol should the mail client use?","options":["POP3","SMTP","IMAP","FTP"],"answer":2,"explanation":"IMAP keeps messages and folders on the server and syncs their state across devices. POP3 usually downloads mail to one device (often deleting it from the server), and SMTP only sends mail.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-204","question":"Which pair of protocols does a mail client typically use to SEND a message and to RECEIVE messages from its mailbox?","options":["IMAP to send, SMTP to receive","HTTP to send, FTP to receive","POP3 to send, IMAP to receive","SMTP to send, IMAP or POP3 to receive"],"answer":3,"explanation":"SMTP pushes mail out to servers; IMAP or POP3 retrieves mail from the user's mailbox. Neither IMAP nor POP3 sends mail.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-205","question":"Which standard lets an e-mail carry attachments such as images and PDFs, and text in scripts like Hindi, even though basic e-mail was designed for plain ASCII text?","options":["MIME","SMTP","HTML","POP3"],"answer":0,"explanation":"MIME (Multipurpose Internet Mail Extensions) encodes attachments and non-ASCII text inside the message. SMTP only transports the message, and HTML formats its body.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-206","question":"In the e-mail address loans.desk@branch.examplebank.in, which part is the domain name?","options":["loans.desk","branch.examplebank.in","examplebank","in"],"answer":1,"explanation":"Everything after @ is the domain that receives the mail (branch.examplebank.in); the part before @ is the mailbox (user) name, and '.in' alone is only the top-level domain.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-207","question":"How many of these statements about e-mail are correct? I. SMTP on its own does not check that the From address really belongs to the sender. II. SPF and DKIM help a receiving server detect mail with a forged sender. III. A message can show a bank's genuine address in its From line even if someone else sent it. IV. The display name shown beside an address can be set to anything by the sender.","options":["One","Two","Three","Four"],"answer":3,"explanation":"All four are correct: SMTP does not verify the sender, SPF and DKIM help detect forgery, the From field can be spoofed to show a genuine bank address, and the display name can be set to anything.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-208","question":"How many of these statements about browser cookies are correct? I. A session cookie is normally deleted when the browser is closed. II. A persistent cookie stays until its expiry date or until the user deletes it. III. A third-party cookie is set by a domain other than the site shown in the address bar, often for ad tracking. IV. Cookies are small programs that run on your computer and can infect it.","options":["One","Two","Four","Three"],"answer":3,"explanation":"I, II and III are correct. IV is false: cookies are small text files of data, not programs, so they cannot run or infect a computer, although they can raise privacy concerns.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-209","question":"Match the HTTP status code with its meaning: 1. 301 2. 403 3. 500 4. 503; a. server temporarily unable to handle the request, e.g. overloaded b. page moved permanently to a new address c. access to the page is forbidden d. internal error on the server","options":["1-b, 2-d, 3-c, 4-a","1-b, 2-c, 3-d, 4-a","1-a, 2-c, 3-d, 4-b","1-b, 2-c, 3-a, 4-d"],"answer":1,"explanation":"3xx codes are redirects (301 = moved permanently), 4xx are client-side problems (403 = forbidden), and 5xx are server-side problems (500 = internal server error, 503 = service unavailable).","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-210","question":"Match each item with what it is: 1. Mozilla Firefox 2. Apache HTTP Server 3. Google Search 4. Wikipedia; a. web browser b. web server software c. search engine d. website","options":["1-c, 2-b, 3-a, 4-d","1-a, 2-d, 3-c, 4-b","1-a, 2-b, 3-c, 4-d","1-b, 2-a, 3-c, 4-d"],"answer":2,"explanation":"A browser (Firefox) displays pages, server software (Apache) delivers them, a search engine (Google Search) indexes and finds them, and a website (Wikipedia) is a collection of pages.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-211","question":"A bank lets its approved vendors log in to a restricted part of its private network to check purchase orders. This arrangement is called:","options":["The internet","An intranet","A LAN","An extranet"],"answer":3,"explanation":"An intranet serves only the organisation's own staff; extending controlled access to outside partners such as vendors makes it an extranet.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-212","question":"An internet plan is advertised at 100 Mbps. A download manager shows speed in MB/s (megabytes per second). Ignoring overheads, what is the highest reading you can expect?","options":["100 MB/s","12.5 MB/s","800 MB/s","1.25 MB/s"],"answer":1,"explanation":"Mbps is megaBITS per second and 1 byte = 8 bits, so 100 ÷ 8 = 12.5 MB/s. 800 MB/s multiplies instead of dividing.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-213","question":"On a web page, what happens when a user clicks a hyperlink of the form mailto:support@examplebank.in?","options":["The default e-mail program opens a new message addressed to that address","The page sends an e-mail automatically without the user seeing it","The browser downloads the support team's contact card","The browser opens the bank's home page"],"answer":0,"explanation":"The mailto: scheme hands the address to the user's default mail client, which opens a new, unsent message; nothing is sent until the user clicks Send.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-214","question":"Assertion (A): Viewing a typical web page involves both HTML and HTTP. Reason (R): HTML is the protocol that carries pages from the server, and HTTP is the language in which pages are written.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true, but R swaps the roles: HTTP is the transfer protocol and HTML is the markup language used to write the page.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-215","question":"A DNS resolver with an empty cache must find the IP address of www.example.in. In which order does it query the DNS hierarchy?","options":["Authoritative server for example.in → .in TLD server → root server","The .in TLD server → root server → authoritative server for example.in","Root server → authoritative server for example.in → .in TLD server","Root server → .in TLD server → authoritative server for example.in"],"answer":3,"explanation":"The root server refers the resolver to the .in TLD servers, which refer it to the authoritative server for example.in, which finally returns the address. Each level only knows the next level down.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-216","question":"Which section of the Information Technology Act, 2000, which punished sending 'offensive' messages through a computer or communication device, was struck down by the Supreme Court in Shreya Singhal v. Union of India (2015)?","options":["Section 66","Section 66A","Section 66C","Section 69A"],"answer":1,"explanation":"The Court held Section 66A unconstitutional as vague and a violation of free speech. In the same case it upheld Section 69A, the government's power to block online content.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-217","question":"Match the section of the IT Act, 2000 with what it deals with: 1. Section 43 2. Section 66D 3. Section 66E 4. Section 67; a. cheating by personation using a computer resource b. publishing obscene material in electronic form c. penalty and compensation for damage to a computer system, such as unauthorised access d. violation of privacy by capturing or publishing private images","options":["1-c, 2-a, 3-d, 4-b","1-c, 2-d, 3-a, 4-b","1-a, 2-c, 3-d, 4-b","1-c, 2-a, 3-b, 4-d"],"answer":0,"explanation":"Section 43 covers civil penalty and compensation for damage to computers, 66D cheating by personation (common in online frauds), 66E violation of privacy and 67 obscene material in electronic form.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-218","question":"Which body is India's national nodal agency for responding to computer security incidents, set up under Section 70B of the IT Act?","options":["NCIIPC","Indian Cyber Crime Coordination Centre (I4C)","CERT-In","National Informatics Centre (NIC)"],"answer":2,"explanation":"CERT-In (Indian Computer Emergency Response Team) is the Section 70B agency. NCIIPC, under Section 70A, protects critical information infrastructure, and I4C coordinates cyber-crime policing.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-219","question":"A rogue bank programmer secretly diverts a few paise from the interest of thousands of accounts into his own account, hoping the tiny amounts go unnoticed. This is a:","options":["Logic bomb","Data diddling attack","Pharming attack","Salami attack"],"answer":3,"explanation":"A salami attack steals tiny 'slices' from many accounts so that no single loss is noticed. Data diddling changes data before or while it is entered, and a logic bomb waits for a trigger condition.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-220","question":"Malware secretly records every key pressed on a cyber-café computer, capturing users' net-banking passwords. Which safeguard offered by many bank websites helps most against this?","options":["Turning on the browser's pop-up blocker","An on-screen virtual keyboard for entering the password","Clearing cookies after logging out","Using the private/incognito window"],"answer":1,"explanation":"A keylogger captures keystrokes, so typing the password by clicking on an on-screen virtual keyboard defeats it. Incognito mode and clearing cookies do not stop malware already installed on the machine.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-221","question":"Attackers take millions of username-password pairs leaked from a shopping site and automatically try them on bank login pages, succeeding wherever people reused passwords. This attack is called:","options":["Brute-force attack","Dictionary attack","Credential stuffing","Session hijacking"],"answer":2,"explanation":"Credential stuffing replays real leaked credentials on other services; it works only because of password reuse. Brute-force and dictionary attacks GUESS passwords instead of using known ones.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-222","question":"An 8-character password can use either only lower-case letters (26 symbols) or upper-case letters, lower-case letters and digits (62 symbols). Roughly how many times larger is the second set of possible passwords?","options":["About 2.4 times","About 19 times","About 36 times","About 1,046 times"],"answer":3,"explanation":"The counts are 26⁸ and 62⁸, so the ratio is (62/26)⁸ ≈ 2.385⁸ ≈ 1,046. 2.4 forgets that the ratio is raised to the power 8, once for each character.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-223","question":"Which measure best lets a branch recover its files after ransomware encrypts every drive on its network and demands payment?","options":["Restoring from recent backups kept offline or otherwise isolated from the network","Restoring from a backup drive that stays permanently connected to the same network","Paying the ransom, since the key is always provided","Renaming the encrypted files back to their original extensions"],"answer":0,"explanation":"Ransomware encrypts everything it can reach, including connected backup drives, so only offline or isolated backups are safe. Paying gives no guarantee of a key, and renaming does not decrypt anything.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-224","question":"An attacker posts a comment containing hidden JavaScript on a bank's poorly coded feedback page. The script then runs in the browsers of other customers who view the page, stealing their session cookies. This is:","options":["SQL injection","Cross-site scripting (XSS)","Clickjacking","A DDoS attack"],"answer":1,"explanation":"XSS injects a malicious script into a page so it runs in OTHER users' browsers. SQL injection targets the database behind the site, and clickjacking hides a real button under a fake one.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-225","question":"In a web search engine, how should you search for pages containing the exact phrase home loan but NOT the word interest?","options":["Put home loan in double quotes and add -interest","Put home loan in double quotes and add the word interest after it","Type home loan interest without any operators","Put interest in double quotes and add -home loan"],"answer":0,"explanation":"Double quotes force the exact phrase, and a minus sign placed directly before a word excludes pages containing it. Adding the word interest without the minus sign would include it instead of excluding it.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-226","question":"A customer gets a text message: 'Your KYC expires today. Update now at this link or your account will be blocked.' This fraud attempt is an example of:","options":["Vishing","Smishing","Whaling","Pharming"],"answer":1,"explanation":"Smishing is phishing by SMS. Vishing uses voice calls, whaling targets top executives, and pharming redirects a genuine web address to a fake site.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-227","question":"A data-entry clerk alters the amounts on vouchers just before keying them into the system, and changes them back later to hide the fraud. This cyber crime is called:","options":["Salami attack","Logic bomb","Data diddling","Email spoofing"],"answer":2,"explanation":"Data diddling is the unauthorised changing of data before or during its entry into a computer. A salami attack instead skims tiny amounts from many accounts.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-228","question":"Which type of malware buries itself deep in the operating system and hides its own files and processes so that antivirus tools and Task Manager cannot see it?","options":["Adware","Worm","Ransomware","Rootkit"],"answer":3,"explanation":"A rootkit's defining feature is concealment at a deep (often kernel) level, which lets other malicious activity stay hidden. Worms spread, ransomware encrypts, and adware shows ads.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-229","question":"A bank's security team deliberately sets up a decoy server that looks vulnerable, so that attackers are drawn to it and their methods can be studied. Such a system is called a:","options":["Honeypot","Firewall","Proxy server","Sandbox"],"answer":0,"explanation":"A honeypot is bait with no real business use, so any traffic to it is suspicious. A sandbox instead runs untrusted programs in isolation, and a firewall filters traffic.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-230","question":"Why can an antivirus that relies only on signature-based detection miss a brand-new virus?","options":["Because new viruses are always encrypted with SSL","Because its database does not yet contain the pattern (signature) of the new virus","Because signature-based scanners check only e-mail attachments","Because it scans only files larger than 1 MB"],"answer":1,"explanation":"Signature scanning matches files against known malware patterns, so unseen (zero-day) malware has no signature yet. Heuristic and behaviour-based detection look for suspicious ACTIONS to close this gap.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-231","question":"A branch takes a full backup on Sunday and an incremental backup each night from Monday to Thursday. Its server crashes on Friday morning. How many backup sets must be restored to get back Thursday night's data?","options":["2","4","1","5"],"answer":3,"explanation":"Each incremental backup holds only the changes since the PREVIOUS backup, so you need Sunday's full backup plus all four incrementals: 5 sets. With differential backups, Sunday's full plus Thursday's differential (2 sets) would be enough.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-232","question":"What does a digital certificate, issued by a Certifying Authority, mainly do?","options":["Binds a public key to the verified identity of its owner","Stores the owner's private key for safe-keeping","Encrypts the whole hard disk of the owner","Blocks viruses from the owner's e-mail"],"answer":0,"explanation":"A certificate is the CA's signed statement that a given public key belongs to a given person or website. The private key never leaves its owner.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-233","question":"A web page shows a 'Play video' button, but an invisible frame from another site is laid over it. Clicking it actually presses a hidden 'Confirm transfer' button. This attack is:","options":["Pharming","Clickjacking","Cross-site scripting","Typosquatting"],"answer":1,"explanation":"Clickjacking (UI redressing) tricks the user into clicking something different from what they see, using transparent layers. Typosquatting uses misspelt domain names.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-234","question":"A bank's office PCs become very slow, with fans running loudly, though no files are damaged. Investigation finds a hidden script using their processors to mine cryptocurrency for an outsider. This is called:","options":["Ransomware","Spyware","Cryptojacking","A logic bomb"],"answer":2,"explanation":"Cryptojacking secretly uses the victim's computing power to mine cryptocurrency; its usual symptom is heavy CPU load, not stolen or encrypted files.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-235","question":"Match the file extension with its file type: 1. .xlsm 2. .xltx 3. .potx 4. .dotx; a. Excel template b. Word template c. PowerPoint template d. macro-enabled Excel workbook","options":["1-a, 2-d, 3-c, 4-b","1-d, 2-a, 3-b, 4-c","1-d, 2-c, 3-a, 4-b","1-d, 2-a, 3-c, 4-b"],"answer":3,"explanation":"In Office formats, a final 'm' means macro-enabled and 't' in 'xlt/pot/dot' means template: xl = Excel, pot = PowerPoint template, dot = Word template.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-236","question":"An Excel workbook with three sheets, formulas and coloured cells is saved as a .csv file. What is kept in the CSV file?","options":["Only the active sheet, with the formulas' current values, and no formatting","All three sheets, with formulas and colours","All three sheets, values only, no formatting","Only the active sheet, with formulas and colours"],"answer":0,"explanation":"CSV is plain text with comma-separated values: it holds one sheet, stores results rather than formulas, and cannot store formatting, which is why Excel warns that features will be lost.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-237","question":"Match each Excel feature with its use: 1. Data Validation 2. Conditional Formatting 3. PivotTable 4. Remove Duplicates; a. summarising thousands of rows by branch and month b. allowing only dates within a range to be entered c. colouring a cell red when the balance falls below the minimum d. deleting repeated account numbers","options":["1-c, 2-b, 3-a, 4-d","1-b, 2-c, 3-a, 4-d","1-b, 2-a, 3-c, 4-d","1-b, 2-c, 3-d, 4-a"],"answer":1,"explanation":"Data Validation restricts what may be entered, Conditional Formatting changes appearance based on values, a PivotTable summarises large data, and Remove Duplicates deletes repeated rows.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-238","question":"A planner wants to save 'best case', 'likely case' and 'worst case' sets of several input values (interest rate, growth, costs) and switch between them to compare results. Which Excel tool is designed for this?","options":["Goal Seek","Data Validation","Scenario Manager","Flash Fill"],"answer":2,"explanation":"Scenario Manager stores named sets of input values and shows each one's effect, even as a summary report. Goal Seek works backwards from one target result by changing a single input.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-239","question":"Match each requirement with the most suitable Excel chart: 1. share of each loan type in the total loan book 2. change in monthly deposits over 24 months 3. relationship between customers' income and loan amount for 200 customers; a. Scatter (XY) chart b. Line chart c. Pie chart","options":["1-b, 2-c, 3-a","1-c, 2-a, 3-b","1-a, 2-b, 3-c","1-c, 2-b, 3-a"],"answer":3,"explanation":"A pie shows parts of one whole, a line shows a trend over time, and a scatter plot shows how two numeric variables relate across many points.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-240","question":"In Excel's default 1900 date system, A1 holds the time 9:00 and B1 holds 11:00. What does the cell with =A1-B1, formatted as time, display?","options":["##### because a negative time cannot be displayed","#VALUE!","#NUM!","−2:00"],"answer":0,"explanation":"The result is a negative fraction of a day, and the 1900 date system cannot show negative dates or times, so the cell fills with #####. It is not an error value: the number −0.0833 is still stored.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-241","question":"In Excel, A2:A7 contain North, South, North, East, North, South and B2:B7 contain 500, 300, 800, 200, 450, 900. What does =COUNTIFS(A2:A7, \"North\", B2:B7, \">450\") return?","options":["3","2","4","6"],"answer":1,"explanation":"COUNTIFS needs BOTH conditions on the same row: the North rows hold 500, 800 and 450, and only 500 and 800 are greater than 450, giving 2. 3 wrongly treats >450 as >=450.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-242","question":"In Excel, A1:A5 contain 50, 80, 80, 60 and 70. What does =RANK(60, A1:A5) return?","options":["3","2","5","4"],"answer":3,"explanation":"RANK sorts in descending order by default and tied values share a rank but still use up places: 80 and 80 are both rank 1, 70 is rank 3, so 60 is rank 4. 3 is the 'dense' rank that skips no places.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-243","question":"What does the Excel formula =RIGHT(\"IFSC0001234\", LEN(\"IFSC0001234\")-4) return?","options":["IFSC","1234","0001234","C0001234"],"answer":2,"explanation":"LEN gives 11, so RIGHT takes the last 11 − 4 = 7 characters: 0001234, i.e. everything after the first four letters. 1234 would need RIGHT(…, 4).","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-244","question":"In Excel, A1 = 60 and B1 = 45. What does =IF(OR(AND(A1>50, B1>50), A1>55), \"Pass\", \"Fail\") return?","options":["Pass","Fail","TRUE","#VALUE!"],"answer":0,"explanation":"AND(60>50, 45>50) is FALSE, but A1>55 is TRUE, so OR(FALSE, TRUE) is TRUE and IF returns 'Pass'. Stopping at the false AND gives the trap 'Fail'.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-245","question":"In Excel, A1:C3 hold 10, 20, 30 in row 1; 40, 50, 60 in row 2; and 70, 80, 90 in row 3. What does =INDEX(A1:C3, 2, 3) return?","options":["80","50","30","60"],"answer":3,"explanation":"INDEX takes the row number first and then the column: row 2, column 3 is cell C2, which holds 60. 80 comes from swapping them (row 3, column 2).","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-246","question":"In Excel, A1:A6 contain Anand, Kiran, Manoj, Rohan, Divya and Chandan. What does =COUNTIF(A1:A6, \"*an\") return?","options":["5","1","3","4"],"answer":2,"explanation":"The * wildcard stands for any characters, so \"*an\" means 'ends with an': Kiran, Rohan and Chandan, giving 3. 5 counts names that merely CONTAIN 'an', and 1 counts names that start with it.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-247","question":"Which Excel formula gives the monthly EMI on a loan of ₹5,00,000 at 12% per annum for 5 years, with monthly payments?","options":["=PMT(12%, 5, 500000)","=PMT(12%/12, 5, 500000)","=PMT(12%, 5*12, 500000)","=PMT(12%/12, 5*12, 500000)"],"answer":3,"explanation":"The rate and the number of periods must both be monthly: 12%/12 = 1% per month for 60 months. The result is about −11,122; PMT shows it as negative because it is money paid out.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-248","question":"An Excel sheet must let users type only in B2:B10 while every other cell stays read-only. Which method works?","options":["Unlock B2:B10 in Format Cells, then protect the sheet","Lock B2:B10 in Format Cells, then protect the sheet","Protect the sheet first; Excel then lets you pick the editable cells automatically","Hide all other rows and columns"],"answer":0,"explanation":"Every cell is formatted 'Locked' by default, but locking takes effect only when the sheet is protected. So unlock the cells that should stay editable, then protect the sheet.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-249","question":"In MS Excel, what does Ctrl + R do when a range such as A1:E1 is selected?","options":["Right-aligns the text in the selected cells","Copies the contents of the leftmost cell into the other selected cells to its right","Repeats the last action","Opens the Replace dialog box"],"answer":1,"explanation":"In Excel, Ctrl + R is Fill Right, just as Ctrl + D is Fill Down. The trap comes from Word, where Ctrl + R right-aligns a paragraph.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-250","question":"While editing a long Excel formula, a user selects the part SUM(B2:B5) in the formula bar and presses F9. What happens?","options":["The whole workbook is recalculated and the formula is unchanged","The selected part is turned into an absolute reference","The selected part is replaced by its calculated value inside the formula","Excel shows an error, because F9 works only outside edit mode"],"answer":2,"explanation":"Pressing F9 in edit mode evaluates the selected part and puts its result into the formula, which is useful for checking; pressing Esc cancels the change. F4, not F9, toggles absolute references.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-251","question":"A user enters =SUM(A1:A5) into cell A1 itself. What happens?","options":["Excel shows #REF!","Excel adds A2:A5 and silently ignores A1","Excel shows #VALUE!","Excel warns of a circular reference, because the formula depends on its own cell"],"answer":3,"explanation":"A formula that refers, directly or indirectly, to its own cell creates a circular reference; Excel warns about it and usually shows 0 instead of looping forever.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-ms-office-internet-252","question":"What does the Excel formula =QUOTIENT(-7, 2) + MOD(-7, 2) return?","options":["-3","-4","-5","-2"],"answer":3,"explanation":"QUOTIENT truncates towards zero, so QUOTIENT(-7, 2) = -3, while MOD takes the sign of the divisor, so MOD(-7, 2) = 1. The sum is -3 + 1 = -2.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-253","question":"What does the Excel formula =COUNT(1, \"2\", \"a\", TRUE) return, where all four values are typed directly as arguments?","options":["1","3","2","4"],"answer":1,"explanation":"When typed directly as arguments, COUNT also counts a number written as text (\"2\") and a logical value (TRUE); only \"a\" is skipped, giving 3. Inside a referenced range, text and TRUE would be ignored.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-254","question":"In Excel, A1 = TRUE, A2 = 2 and A3 holds the text \"3\". What do =SUM(A1:A3) and =SUM(TRUE, 2, \"3\") return respectively?","options":["6 and 6","2 and 2","2 and 6","6 and 2"],"answer":2,"explanation":"SUM ignores logical values and numbers stored as text inside a range, so the first gives 2. Typed directly as arguments, TRUE counts as 1 and \"3\" as 3, so the second gives 6.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-255","question":"What does the Excel formula =(5>3) + (2>4) + TRUE return?","options":["2","1","TRUE","#VALUE!"],"answer":0,"explanation":"In arithmetic, Excel treats TRUE as 1 and FALSE as 0. (5>3) is TRUE, (2>4) is FALSE, so the result is 1 + 0 + 1 = 2.","difficulty":"hard","source":"SBI Clerk Mains · SSC CGL"},
  {"id":"comp-ms-office-internet-256","question":"What does the Excel formula =DAY(DATE(2024, 3, 0)) return?","options":["28","31","29","#NUM!"],"answer":2,"explanation":"Day 0 of a month is the last day of the previous month, so DATE(2024, 3, 0) is 29 February 2024 (a leap year), and DAY gives 29.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-257","question":"What does =DATEDIF(DATE(2000, 5, 15), DATE(2024, 5, 14), \"Y\") return in Excel?","options":["24","22","#NUM!","23"],"answer":3,"explanation":"The \"Y\" unit counts only complete years. The 24th anniversary falls on 15 May 2024, one day after the end date, so only 23 full years have passed.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-258","question":"1 January 2024 was a Monday. What does =NETWORKDAYS(DATE(2024, 1, 1), DATE(2024, 1, 14)) return in Excel?","options":["9","10","12","14"],"answer":1,"explanation":"NETWORKDAYS counts Monday-to-Friday days with both end dates included. 1 to 14 January is exactly two full weeks, so 2 × 5 = 10 working days.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-259","question":"In Excel, A1:D1 contain Q1, Q2, Q3, Q4 and A2:D2 contain 120, 150, 90, 200. What does =HLOOKUP(\"Q3\", A1:D2, 2, FALSE) return?","options":["150","90","200","#N/A"],"answer":1,"explanation":"HLOOKUP finds Q3 in the top row (column C) and returns the value from row 2 of that column, which is 90.","difficulty":"moderate","source":"SBI Clerk Mains · SSC CHSL"},
  {"id":"comp-ms-office-internet-260","question":"3 January 2024 was a Wednesday. What does =CHOOSE(WEEKDAY(DATE(2024, 1, 3)), \"Sun\", \"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\") return?","options":["Wed","Tue","Thu","Mon"],"answer":0,"explanation":"With its default type, WEEKDAY numbers Sunday as 1, so a Wednesday gives 4, and CHOOSE picks the 4th item, \"Wed\". Answering Tue assumes Monday = 1.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-261","question":"What does the Excel formula =MEDIAN(23, 4, 42, 15, 8, 16) return?","options":["28.5","18","15.5","15"],"answer":2,"explanation":"Sorted, the values are 4, 8, 15, 16, 23, 42. With an even count, the median is the average of the middle two: (15 + 16) / 2 = 15.5. 18 is the mean, and 28.5 comes from not sorting first.","difficulty":"moderate","source":"SBI Clerk Mains · SSC CGL"},
  {"id":"comp-ms-office-internet-262","question":"In Excel, A1 contains \"Rohit Kumar Sharma\". What does =MID(A1, FIND(\" \", A1) + 1, FIND(\" \", A1, FIND(\" \", A1) + 1) - FIND(\" \", A1) - 1) return?","options":["Sharma","Kumar Sharma","umar S","Kumar"],"answer":3,"explanation":"The first space is at position 6 and the second at 12. MID starts at 7 and takes 12 - 6 - 1 = 5 characters, giving the middle name \"Kumar\".","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-263","question":"A2:A7 contain North, South, North, North, East, South; B2:B7 contain 5, 8, 12, 3, 9, 10; C2:C7 contain 100, 200, 300, 400, 500, 600. What does =SUMIFS(C2:C7, A2:A7, \"North\", B2:B7, \">4\") return?","options":["400","800","1700","300"],"answer":0,"explanation":"Both conditions must hold in the same row: North rows have B values 5, 12 and 3, and only 5 and 12 are above 4, so 100 + 300 = 400. 800 ignores the second condition.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-264","question":"In Excel, A1:A6 contain Ram, Raja, Ravi, Rani, Rajiv and Roy. What does =COUNTIF(A1:A6, \"Ra??\") return?","options":["5","4","3","2"],"answer":2,"explanation":"Each ? stands for exactly one character, so \"Ra??\" matches four-letter names starting with Ra: Raja, Ravi and Rani. \"Ra*\" would have matched 5, adding Ram and Rajiv.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-265","question":"In Excel, A1 = 45, A2 holds the text \"90\", A3 = TRUE, A4 = 60 and A5 is blank. What does =MAX(A1:A5) return?","options":["90","1","60","0"],"answer":2,"explanation":"When MAX reads a range, it ignores text (even number-like text), logical values and blanks, so only 45 and 60 are compared.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-266","question":"What does the Excel formula =ROUNDUP(2.001, 0) + ROUNDDOWN(2.999, 0) return?","options":["4","5","6","3"],"answer":1,"explanation":"ROUNDUP always moves away from zero (2.001 to 3) and ROUNDDOWN always towards zero (2.999 to 2), whatever the next digit, so 3 + 2 = 5.","difficulty":"moderate","source":"SSC CGL · SBI Clerk"},
  {"id":"comp-ms-office-internet-267","question":"What does the Excel formula =ISNUMBER(\"5\") + ISNUMBER(5) + ISTEXT(\"5\") return?","options":["3","1","#VALUE!","2"],"answer":3,"explanation":"\"5\" in quotes is text, so ISNUMBER(\"5\") is FALSE (0) and ISTEXT(\"5\") is TRUE (1); ISNUMBER(5) is TRUE (1). The sum is 2.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-268","question":"What do =IF(\"abc\"=\"ABC\", \"Same\", \"Different\") and =IF(EXACT(\"abc\", \"ABC\"), \"Same\", \"Different\") return respectively?","options":["Same and Same","Different and Different","Different and Same","Same and Different"],"answer":3,"explanation":"The = operator compares text without regard to case, so the first gives Same. EXACT is case-sensitive, so the second gives Different.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-269","question":"In Excel, A1 holds the date 31 January 2024. Which date does =A1 + 30 show?","options":["2 March 2024","1 March 2024","29 February 2024","28 February 2024"],"answer":1,"explanation":"Adding a number to a date adds days. 2024 is a leap year, so 31 January + 29 days is 29 February and + 30 days is 1 March 2024.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-270","question":"In Excel, A1 contains 2.5 but is formatted with 0 decimal places, so it shows 3. What does =A1*2 return?","options":["5","6","3","4"],"answer":0,"explanation":"Number formatting changes only the display; the stored value is still 2.5, so the formula gives 5. Using the shown value would give 6.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-271","question":"In Excel, A1 contains the number 12.50, formatted to show two decimal places. What does =LEN(A1) return?","options":["5","2","4","#VALUE!"],"answer":2,"explanation":"LEN works on the stored value, 12.5, not on the formatted display, so it counts \"12.5\", which is 4 characters.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-272","question":"A2:A6 contain Amit, Bina, Chirag, Deepa, Esha and B2:B6 contain 78, 91, 85, 91, 66. What does =INDEX(A2:A6, MATCH(MAX(B2:B6), B2:B6, 0)) return?","options":["Bina","Deepa","91","#N/A"],"answer":0,"explanation":"MAX gives 91, and MATCH with 0 returns the position of the FIRST 91, which is 2, so INDEX gives Bina even though Deepa has the same mark.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-273","question":"In Excel's default 1900 date system, what does the formula =\"Due: \" & DATE(2024, 1, 1) return?","options":["Due: 01-01-2024","Due: 1 Jan 2024","#VALUE!","Due: 45292"],"answer":3,"explanation":"The & operator joins the underlying serial number of the date, which for 1 January 2024 is 45292; the date format is lost. TEXT(DATE(2024,1,1), \"dd-mm-yyyy\") would keep it readable.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-274","question":"What does the Excel formula =ROUND(15.5, 0) + ROUND(-15.5, 0) return?","options":["1","32","31","0"],"answer":3,"explanation":"Excel's ROUND sends a 5 away from zero on both sides, so 15.5 becomes 16 and -15.5 becomes -16, giving 0. Answering 1 assumes -15.5 rounds up to -15.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-275","question":"How many capital letters are there in the result of the Excel formula =PROPER(\"o'neil mcDONALD\")?","options":["2","3","4","5"],"answer":1,"explanation":"PROPER capitalises the first letter of the text and every letter that follows a non-letter (an apostrophe counts), and lower-cases the rest, giving O'Neil Mcdonald: capitals O, N and M.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-276","question":"Which formula correctly adds C2:C7 only for rows where A2:A7 is \"North\" and B2:B7 is greater than 4?","options":["=SUMIFS(C2:C7, A2:A7, \"North\", B2:B7, \">4\")","=SUMIFS(A2:A7, \"North\", B2:B7, \">4\", C2:C7)","=SUMIF(A2:A7, \"North\", C2:C7, B2:B7, \">4\")","=SUMIFS(C2:C7, \"North\", A2:A7, \">4\", B2:B7)"],"answer":0,"explanation":"SUMIFS puts the sum range first, then criteria range and criterion pairs, with text and comparison criteria in quotes. SUMIF takes only one condition, with the sum range last.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-277","question":"What does the Excel formula =FV(10%, 2, 0, -1000) return?","options":["1331","1200","1210","1100"],"answer":2,"explanation":"FV compounds the present value: 1000 × 1.1² = 1210. The PV is entered as negative (money paid out), so the future value comes out positive.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-278","question":"In Excel, the range A1:A10 is selected, the word Pending is typed and Ctrl + Enter is pressed. What happens?","options":["Pending is entered into all ten selected cells at once","Pending is entered into A1 and the cursor moves down to A2","A line break is inserted inside A1 after the word Pending","Pending is entered into A1 and the selection is cleared"],"answer":0,"explanation":"Ctrl + Enter fills every cell of the current selection with the same entry. Alt + Enter is the shortcut that adds a line break inside one cell.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-279","question":"In Excel, A1 contains =B1*2. With A2 selected, the user presses Ctrl + ' (apostrophe) and then Enter. What does A2 now contain?","options":["=B2*2, adjusted to the new row","Only the value of A1, not the formula","=B1*2, exactly as in A1","=$B$1*2, with the reference made absolute"],"answer":2,"explanation":"Ctrl + ' copies the formula of the cell above without adjusting its references, unlike Ctrl + D (fill down), which would give =B2*2.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-280","question":"Which pair of Excel shortcuts hides the selected rows and the selected columns respectively?","options":["Ctrl + 0 and Ctrl + 9","Ctrl + 9 and Ctrl + 0","Ctrl + 8 and Ctrl + 9","Ctrl + 5 and Ctrl + 6"],"answer":1,"explanation":"Ctrl + 9 hides rows and Ctrl + 0 hides columns; Ctrl + Shift + 9 unhides rows. Ctrl + 5 applies strikethrough and Ctrl + 8 shows or hides outline symbols.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-281","question":"In Excel, which shortcuts select the entire row and the entire column of the active cell respectively?","options":["Ctrl + Space and Shift + Space","Ctrl + Shift + Right and Ctrl + Shift + Down","Alt + Space and Ctrl + Shift + Space","Shift + Space and Ctrl + Space"],"answer":3,"explanation":"Shift + Space selects the whole row and Ctrl + Space the whole column. Ctrl + Shift + arrow only extends the selection to the end of the data block.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-282","question":"In Excel, A1 contains 0.075. It is selected and Ctrl + Shift + % is pressed. What does the cell show?","options":["8%","7.5%","0.075%","75%"],"answer":0,"explanation":"Ctrl + Shift + % applies the Percentage format with no decimal places, so 0.075 (that is, 7.5%) is displayed rounded as 8%, though the stored value is unchanged.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-283","question":"In MS Excel, what does pressing Shift + F11 do?","options":["Creates a chart of the data on a new chart sheet","Opens the Save As dialog box for the workbook","Opens the Visual Basic editor for macros","Inserts a new worksheet into the workbook"],"answer":3,"explanation":"Shift + F11 inserts a new worksheet. F11 alone makes a chart sheet, F12 opens Save As and Alt + F11 opens the VBA editor.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-284","question":"In MS Excel, which shortcut moves to the next worksheet tab in the same workbook?","options":["Ctrl + Page Up","Alt + Page Down","Ctrl + Page Down","Ctrl + Tab"],"answer":2,"explanation":"Ctrl + Page Down goes to the next sheet and Ctrl + Page Up to the previous one. Alt + Page Down scrolls one screen right, and Ctrl + Tab switches between open workbooks.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk"},
  {"id":"comp-ms-office-internet-285","question":"In Excel, a user fills cell B2 with yellow, then selects D7 and presses F4 while NOT editing any formula. What happens?","options":["D7 is changed into the absolute reference $D$7","D7 is filled yellow too, as F4 repeats the last action","Nothing happens, as F4 works only inside a formula","The workbook closes, as it would with Ctrl + F4"],"answer":1,"explanation":"Outside formula editing, F4 (like Ctrl + Y) repeats the last action. It cycles $ signs only while a reference is being edited in a formula.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-286","question":"What does the shortcut Shift + F3 do in MS Word and in MS Excel respectively?","options":["Opens Insert Function in Word; changes case in Excel","Changes the case of selected text in both programs","Finds the next match in Word; opens Name Manager in Excel","Changes case in Word; opens Insert Function in Excel"],"answer":3,"explanation":"The same key does different jobs: in Word Shift + F3 cycles the case of selected text, while in Excel it opens the Insert Function dialog.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-287","question":"Which of these can make an Excel cell display ##### ? I. The column is too narrow for the number. II. The cell holds a negative date or time value. III. The formula divides a number by zero. IV. The formula refers to a deleted cell.","options":["Only I","Only I and II","Only I, II and III","All four of them"],"answer":1,"explanation":"##### appears when a number does not fit the column or when a date/time works out negative. Dividing by zero gives #DIV/0! and a deleted reference gives #REF!.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-288","question":"In Excel, D1 contains =B1+C1. The cell is CUT (Ctrl + X) and pasted into F5. What formula does F5 now contain?","options":["=D5+E5","=B5+C5","=B1+C1","=D1+E1"],"answer":2,"explanation":"Moving a formula by cut and paste keeps its references exactly as they were. Copying it to F5 instead would have shifted them two columns right and four rows down, giving =D5+E5.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-289","question":"In Excel, A10 contains =SUM(A1:A9). A new row is then inserted above row 5. What is the formula now and where is it?","options":["=SUM(A1:A10) in cell A11","=SUM(A1:A9) in cell A11","=SUM(A1:A10) in cell A10","=SUM(A2:A10) in cell A11"],"answer":0,"explanation":"Inserting a row inside the range pushes the formula down to A11 and expands the range it refers to, so it still covers all the original cells plus the new row.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-290","question":"A formula must use cell B4 of another sheet whose name is Sales 2024 (with a space). What must be done to the sheet name in the reference?","options":["Put it in single quotes before the ! sign","Put it in double quotes before the ! sign","Put it in square brackets before the cell","Put a $ sign before it to fix the sheet"],"answer":0,"explanation":"A sheet name with spaces must be enclosed in single quotes, as in ='Sales 2024'!B4. Square brackets are used for a workbook name in external references.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-291","question":"In Excel, cell F1 is given the name Rate, and C2 contains =B2*Rate. C2 is copied to C3 and to D2. Which cell do the copies use for Rate?","options":["F2 in C3 and G1 in D2, like a relative one","F1 in both copies, like an absolute reference","F2 in C3 but F1 in D2, like a mixed reference","Neither, both copies show a #NAME? error"],"answer":1,"explanation":"A name defined for a single cell refers to it absolutely ($F$1 by default), so every copy of the formula keeps pointing to F1.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-292","question":"In Excel, cell B2 contains =A1. It is copied and pasted into cell B1. What does B1 then contain?","options":["=A1","=B1, a circular reference","=A2","=#REF!"],"answer":3,"explanation":"Copying one row up shifts the relative reference A1 up by one row to a row 0, which does not exist, so Excel writes the #REF! error into the formula.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-293","question":"A user wants Excel to store one-half as the number 0.5 but show it as the fraction 1/2. What should be typed into the cell?","options":["1/2","'1/2 (with an apostrophe first)","0 1/2 (zero, a space, then 1/2)","=1/2 (as a formula)"],"answer":2,"explanation":"Typing a zero and a space before 1/2 makes Excel enter the fraction 0.5 with a fraction format. Plain 1/2 is read as a date, '1/2 becomes text and =1/2 shows 0.5.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-294","question":"In Excel, only A1 (containing 1) is selected and its fill handle is dragged to A5. This is done once normally and once while holding Ctrl. What does A5 show each time?","options":["5 normally, and 1 with Ctrl held","5 both times, as a series","1 normally, and 5 with Ctrl held","1 both times, as a copy"],"answer":2,"explanation":"Dragging a single number copies it, while holding Ctrl makes a series 1, 2, 3, 4, 5. With two numbers selected, a plain drag would continue the series.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-295","question":"All salaries in C2:C50 must be raised by 10% in place, without a helper column. A user types 1.1 in a spare cell and copies it. What should be done next?","options":["Select C2:C50, open Paste Special and choose Multiply","Select C2:C50, open Paste Special and choose Add","Select C2:C50, open Paste Special and choose Values","Select C2:C50 and press Ctrl + V to paste directly"],"answer":0,"explanation":"Paste Special with the Multiply operation multiplies each target cell by the copied 1.1. Add would only increase each salary by 1.1 rupees, and a plain paste would overwrite them.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-296","question":"A column holds names written as Sharma, Amit. Which Excel feature splits them into separate surname and first-name columns at the comma in one operation?","options":["Merge and Center","Wrap Text","Consolidate","Text to Columns"],"answer":3,"explanation":"Data > Text to Columns splits each cell at a delimiter such as a comma. Merge and Center joins cells, Wrap Text only wraps lines, and Consolidate combines data from several ranges.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL"},
  {"id":"comp-ms-office-internet-297","question":"A loan officer wants a grid showing the EMI from one PMT formula for interest rates of 8%, 9%, 10% and 11% at once. Which What-If Analysis tool does this?","options":["Goal Seek","Data Table","Scenario Manager","Remove Duplicates"],"answer":1,"explanation":"A Data Table recalculates one formula for a list of input values and fills a grid. Goal Seek works backwards from a single target result, and Scenario Manager stores named sets of inputs.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-298","question":"Which Excel feature draws a tiny line or column chart inside a single cell to show the trend of the values in that row?","options":["Data Bars","Sparklines","Slicers","Trendline"],"answer":1,"explanation":"Sparklines are mini charts inside a cell showing a trend across several values. Data Bars shade each cell by its own single value, and Slicers are buttons for filtering.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-299","question":"A sales list in B2:B10 is filtered to show only North rows. Which formula totals only the rows that are now visible?","options":["=SUBTOTAL(9, B2:B10)","=SUM(B2:B10)","=SUBTOTAL(1, B2:B10)","=SUMIF(B2:B10, \">0\")"],"answer":0,"explanation":"SUBTOTAL with function number 9 (sum) ignores rows hidden by a filter. SUM and SUMIF add every row, and SUBTOTAL(1, …) would give an average instead.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-300","question":"In Excel, what does =IF(A1>5, Yes, No) return when A1 = 8?","options":["Yes","#VALUE!","#N/A","#NAME?"],"answer":3,"explanation":"Text in a formula must be inside double quotes. Without them Excel treats Yes and No as undefined names and returns #NAME?.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-301","question":"An Excel workbook is set to Manual calculation, so formulas do not update after an input is changed. Which key recalculates all open workbooks?","options":["F2","F4","F9","F7"],"answer":2,"explanation":"F9 recalculates formulas. F2 edits the active cell, F4 toggles references or repeats the last action, and F7 runs the spell check.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk"},
  {"id":"comp-ms-office-internet-302","question":"In MS Excel, what does pressing Ctrl + T with any cell of a data range selected do?","options":["Applies a hanging indent to the text in the active cell","Converts the range into a Table with filters and banded rows","Opens the Find and Replace dialog on the Replace tab","Turns on Track Changes for the whole worksheet"],"answer":1,"explanation":"In Excel, Ctrl + T (like Ctrl + L) creates a Table with filter buttons, banded rows and automatic expansion. In Word the same key gives a hanging indent.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-303","question":"In MS Word, selected text in a centred paragraph is bold, italic, red and 16 pt (all applied by hand). What happens when Ctrl + Space is pressed?","options":["The bold, italic, colour and size go back to the style default, and the paragraph stays centred","The paragraph loses its centring, but the bold, italic, colour and size stay as they are","Both the character formatting and the centring are removed in one go","A non-breaking space replaces the selected text"],"answer":0,"explanation":"Ctrl + Space removes manual CHARACTER formatting only. Ctrl + Q is the shortcut that removes manual paragraph formatting such as alignment and indents.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-304","question":"Match the MS Word shortcut with what it applies: 1. Ctrl + Shift + N 2. Ctrl + Alt + 1 3. Ctrl + Shift + L 4. Ctrl + Shift + K; a. Heading 1 style b. Small caps c. Normal style d. List Bullet style","options":["1-a, 2-c, 3-d, 4-b","1-c, 2-a, 3-d, 4-b","1-c, 2-a, 3-b, 4-d","1-c, 2-d, 3-a, 4-b"],"answer":1,"explanation":"Ctrl + Shift + N gives the Normal style, Ctrl + Alt + 1 gives Heading 1, Ctrl + Shift + L gives the List Bullet style and Ctrl + Shift + K gives small capitals.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-305","question":"In MS Word, the shortcut Ctrl + Shift + W is applied to the selected words Fixed Deposit Rates. What is the result?","options":["The whole selection gets a double underline, spaces included","The whole selection gets a single wavy red underline","Each word is underlined but the spaces between them are not","The document is closed after asking to save the changes"],"answer":2,"explanation":"Ctrl + Shift + W gives a words-only underline. Ctrl + Shift + D gives a double underline, and Ctrl + W (without Shift) closes the document.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-306","question":"Match the MS Word key with its effect on fields: 1. F9 2. Alt + F9 3. Ctrl + Shift + F9 4. Ctrl + F9; a. inserts a pair of empty field braces b. turns the field into plain text that no longer updates c. switches all fields between codes and results d. updates the selected fields","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a"],"answer":3,"explanation":"F9 updates fields, Alt + F9 toggles field codes for the whole document, Ctrl + Shift + F9 unlinks fields into fixed text, and Ctrl + F9 inserts empty field braces.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-307","question":"After new headings are added to a long Word report, its automatic Table of Contents still shows the old headings and page numbers. What is the quickest fix?","options":["Press Ctrl + Enter at the start of the table of contents","Retype the new headings into the table of contents","Press Ctrl + Z until the table of contents changes","Click in the table of contents and press F9 to update it"],"answer":3,"explanation":"A Table of Contents is a field, so it changes only when updated (F9 or Update Table), where you can refresh page numbers only or the entire table.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-308","question":"Which of these statements about formulas in an MS Word table are correct? I. =SUM(ABOVE) in a cell adds the numbers above it in that column. II. The result recalculates automatically as soon as a number above it is changed. III. Table cells can be referred to in A1 style, with columns as letters and rows as numbers.","options":["I and II only","I and III only","I, II and III","III only"],"answer":1,"explanation":"Word table formulas support ABOVE, LEFT and A1-style cell references, but the result is a field that does not recalculate by itself; you must update it with F9.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-309","question":"A Word document has an empty line between every pair of paragraphs, made by pressing Enter twice. Using Find and Replace, what should be found and what should it be replaced with to remove these empty lines?","options":["Find ^t^t and replace with ^t","Find ^p and replace with ^t","Find ^p^p and replace with ^p","Find ^l^l and replace with ^p"],"answer":2,"explanation":"In Word's Find and Replace, ^p stands for a paragraph mark (Enter), ^t for a tab and ^l for a manual line break, so two paragraph marks are replaced by one.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-310","question":"In Word's Find dialog, Use wildcards is ticked and b?t is searched in the line: bat boat bit bet but. How many matches are found?","options":["3","5","4","1"],"answer":2,"explanation":"With wildcards on, ? stands for exactly one character, so b?t matches bat, bit, bet and but: four matches. Boat has two letters between b and t; * would have matched it.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-311","question":"In a book being typed in MS Word for double-sided printing, every chapter must begin on a right-hand page, even if a blank page is needed before it. Which break should be placed before each chapter?","options":["Section break (Continuous)","Section break (Next Page)","Section break (Odd Page)","Column break"],"answer":2,"explanation":"In double-sided printing, right-hand pages are odd-numbered. An Odd Page section break starts the next section on the next odd page and leaves a blank even page if needed.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-312","question":"In a double-sided Word report, page numbers must appear at the outer edge of each page: the right side on odd pages and the left side on even pages. Which header/footer option makes this possible?","options":["Different Odd and Even Pages","Different First Page","Mirror Margins in Page Setup","Link to Previous"],"answer":0,"explanation":"Different Odd and Even Pages gives separate footers for odd and even pages, so the number can be right-aligned on one and left-aligned on the other. Mirror Margins changes margins, not footers.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-313","question":"A Word document has two sections. The user types a new header in section 2, but the header of section 1 also changes to match. What must be done?","options":["Turn on Different First Page in the header of section 1","Turn off Link to Previous in the header of section 2","Replace the section break with a manual page break","Turn on Different Odd and Even Pages in section 2"],"answer":1,"explanation":"By default, each section's header is linked to the previous section's header. Breaking Link to Previous in section 2 lets the two sections have different headers.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-314","question":"A magazine article in MS Word must start with a large first letter that drops down across the first three lines of the paragraph. Which feature does this?","options":["WordArt","Small Caps","Text Box","Drop Cap"],"answer":3,"explanation":"Drop Cap (Insert tab) enlarges the first letter and sinks it into the paragraph over a set number of lines. Small Caps only changes lower-case letters into small capitals.","difficulty":"moderate","source":"SSC CHSL · SBI Clerk"},
  {"id":"comp-ms-office-internet-315","question":"A Word mail merge uses an Excel list of 500 customers, but letters are needed only for customers whose balance is below ₹1,000. The Excel file must not be changed. What should be done?","options":["Filter the recipient list on the balance field in Edit Recipient List","Delete the unwanted rows from the Excel file before merging","Merge all 500 letters and then delete the unwanted ones","Insert a Next Record field after the balance in the main document"],"answer":0,"explanation":"Edit Recipient List lets you filter (or untick) records by a field such as balance, so only matching records are merged, without touching the data source.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-316","question":"A report in Word numbers its pictures as Figure 1, Figure 2 and so on, using Insert Caption. Which feature then builds a list of all the figures with their page numbers?","options":["Table of Contents","Table of Figures","Index","Bibliography"],"answer":1,"explanation":"Table of Figures (References tab) is built from captions. A Table of Contents is built from heading styles and an Index from marked index entries.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-317","question":"In MS Word, which shortcut marks the selected word as an entry for the index at the back of the document?","options":["Alt + Shift + O","Alt + Ctrl + F","Alt + Shift + X","Alt + Ctrl + D"],"answer":2,"explanation":"Alt + Shift + X opens Mark Index Entry. Alt + Shift + O marks a table-of-contents entry, while Alt + Ctrl + F and Alt + Ctrl + D insert a footnote and an endnote.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-318","question":"An officer has two versions of a circular saved as separate Word files, and Track Changes was never turned on. Which feature shows every difference between them as tracked changes?","options":["Restrict Editing (Review tab)","Accept All Changes (Review tab)","Inspect Document (File tab)","Compare (Review tab)"],"answer":3,"explanation":"Review > Compare takes an original and a revised file and produces a document showing the differences as tracked changes. Accept All only works on changes already tracked.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-319","question":"In MS Word, text is selected and Ctrl + Shift + H is pressed. What happens to it?","options":["It is highlighted in yellow, like with the Highlighter tool","It is changed into a heading in the Navigation pane","It becomes hidden text, not shown unless formatting marks are on","It is replaced with the next match of the Replace box"],"answer":2,"explanation":"Ctrl + Shift + H applies the Hidden font format: the text disappears from view (and normally from print) but shows with a dotted underline when Show/Hide ¶ is on.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-320","question":"Which view in MS Word shows a document as a hierarchy of headings, so that a whole section can be promoted, demoted or moved together with its text?","options":["Outline view","Draft view","Web Layout view","Read Mode"],"answer":0,"explanation":"Outline view displays heading levels and lets you move or promote a heading with everything under it. Draft view is a plain typing view without headers or most graphics.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL"},
  {"id":"comp-ms-office-internet-321","question":"A list in Word has codes at the start of each line (such as A101, B202). How can just the first four characters of every line be selected as a vertical block?","options":["Triple-click in the first line, then drag down the list","Hold Ctrl and click on each line in turn","Hold Shift and press the Down arrow key","Hold Alt and drag down over the first four characters"],"answer":3,"explanation":"Alt + drag makes a rectangular (column) selection. A triple-click selects a paragraph, Ctrl + click selects a sentence, and Shift + Down selects whole lines.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-322","question":"In MS Word the cursor is inside a word in the middle of a sentence. F8 is pressed three times. What is selected now?","options":["The current word","The whole sentence","The whole paragraph","The whole document"],"answer":1,"explanation":"The first F8 turns on extend mode, the second selects the word, the third the sentence, then the paragraph and finally the whole document.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-323","question":"In a Word report, a heading keeps appearing alone at the bottom of a page while its first paragraph starts on the next page. Which paragraph option should be set on the heading?","options":["Widow/Orphan control","Page break before","Keep with next","Keep lines together"],"answer":2,"explanation":"Keep with next keeps a paragraph on the same page as the next one. Widow/Orphan control works on single lines of one paragraph, and Keep lines together stops one paragraph from splitting.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-324","question":"A Word table spreads over four pages. Which option makes its column titles appear again at the top of each page?","options":["Repeat Header Rows","Merge Cells","Allow row to break across pages","AutoFit to Contents"],"answer":0,"explanation":"Repeat Header Rows (Table Layout) repeats the marked first row(s) on every page the table runs onto. Allow row to break only controls whether one row may split.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk"},
  {"id":"comp-ms-office-internet-325","question":"By default, a picture inserted into an MS Word document is placed with which text wrapping?","options":["Top and Bottom","Tight","In Front of Text","In Line with Text"],"answer":3,"explanation":"Unless the default is changed in Options, Word inserts a picture In Line with Text, so it behaves like a big character. Top and Bottom, Tight and In Front of Text make it a floating object.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-326","question":"Match the MS Word shortcut with the symbol it inserts: 1. Ctrl + Alt + C 2. Ctrl + Alt + R 3. Ctrl + Alt + T; a. ™ (trademark) b. © (copyright) c. ® (registered)","options":["1-b, 2-a, 3-c","1-b, 2-c, 3-a","1-c, 2-b, 3-a","1-a, 2-c, 3-b"],"answer":1,"explanation":"Ctrl + Alt + C inserts ©, Ctrl + Alt + R inserts ® and Ctrl + Alt + T inserts ™. AutoCorrect also turns (c), (r) and (tm) into these symbols.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-327","question":"A user records a macro in MS Word and keeps the default choice of where to store it. Why can the macro be used in every new document afterwards?","options":["It is stored inside the current document and copied to others when opened","It is stored in the Normal.dotm template that all new documents are based on","It is stored as a separate .docm file that Word opens with each document","It is stored in the Quick Access Toolbar, which keeps a copy of the code"],"answer":1,"explanation":"Word's default location for a recorded macro is All Documents (Normal.dotm), the global template behind every new blank document. A .docm keeps macros only inside that file.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-328","question":"On a PowerPoint slide the title appears on a click. A chart must then appear by itself 2 seconds after the title's animation ends, with no further click. How should the chart's animation be set?","options":["Start: After Previous, with a Delay of 2 seconds","Start: With Previous, with a Duration of 2 seconds","Start: On Click, with a Delay of 2 seconds","Start: With Previous, with no delay at all"],"answer":0,"explanation":"After Previous starts an effect when the one before it ends, and Delay adds the wait. With Previous starts at the same moment as the title, and On Click still needs a click.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-329","question":"In PowerPoint, a logo already shown on a slide must fade away from the slide when the presenter clicks. Which group of animation effects should be used?","options":["Entrance","Emphasis","Transition","Exit"],"answer":3,"explanation":"Exit effects make an object leave the slide. Entrance effects bring it in, Emphasis effects act on it while it stays, and a transition acts between slides, not on one object.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL"},
  {"id":"comp-ms-office-internet-330","question":"In PowerPoint, a car picture must travel across a map slide along a curved route drawn by the presenter. Which kind of animation does this?","options":["Emphasis (Spin)","Motion Path","Entrance (Fly In)","Morph transition"],"answer":1,"explanation":"A Motion Path moves an object along a line or a custom path you draw. Fly In only brings the object in from an edge, and Spin rotates it in place.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-331","question":"Match the key pressed during a PowerPoint slide show with its effect: 1. Ctrl + P 2. E 3. Ctrl + H 4. Esc; a. ends the slide show b. hides the mouse pointer c. erases the ink drawn on the slide d. changes the pointer into a pen","options":["1-d, 2-b, 3-c, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b"],"answer":2,"explanation":"In a slide show, Ctrl + P gives a pen, E erases the ink on the slide, Ctrl + H hides the pointer and Esc ends the show.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-332","question":"During a PowerPoint slide show on slide 12 of 30, what do the Home and End keys do?","options":["Home jumps to slide 1 and End jumps to slide 30","Home jumps to slide 11 and End jumps to slide 13","Home ends the show and End returns to Normal view","Home shows a black screen and End shows a white one"],"answer":0,"explanation":"In a slide show, Home goes to the first slide and End to the last. The previous and next slides use keys such as P/N, arrows or Page Up/Page Down.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-333","question":"A trainer wants the printed handouts of a PowerPoint deck to carry the bank's logo and a footer on every handout page, without changing the slides themselves. Where should this be set up?","options":["Slide Master","Notes Master","Handout Master","Slide Sorter view"],"answer":2,"explanation":"The Handout Master controls the layout of printed handout pages. The Slide Master changes the slides, and the Notes Master changes printed notes pages.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-334","question":"Which PowerPoint view shows each slide at the top of a page with its speaker notes below it, exactly as it will look when notes are printed?","options":["Normal view","Slide Sorter view","Outline view","Notes Page view"],"answer":3,"explanation":"Notes Page view shows the printable page with a slide and its notes, and lets you add graphics to the notes. Normal view shows notes only in a small pane.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-335","question":"A 40-slide deck is shown to the board, but only slides 3, 8, 15 and 22 are needed for a branch meeting. Without deleting or hiding anything, which feature lets these be presented as a separate show?","options":["Rehearse Timings","Custom Slide Show","Slide Sorter view","Reuse Slides"],"answer":1,"explanation":"A Custom Slide Show is a named list of chosen slides in any order that can be run on its own, while the full deck stays unchanged.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-336","question":"A presenter wants a PowerPoint show with manual slide changes to start again from the first slide after the last one, and to keep repeating until Esc is pressed. Which Set Up Show option does this?","options":["Browsed at a kiosk (full screen)","Show without animation","Use Presenter View","Loop continuously until Esc"],"answer":3,"explanation":"Loop continuously until Esc repeats the show. Kiosk mode also loops but ignores ordinary clicks, so a presenter could not advance the slides by hand.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-337","question":"A song inserted on the first slide of a PowerPoint photo album stops as soon as the next slide appears. Which audio setting keeps it playing over the following slides?","options":["Play Across Slides","Hide During Show","Rewind after Playing","Start: On Click"],"answer":0,"explanation":"Play Across Slides (part of Play in Background) keeps the sound going when slides change. Hide During Show only hides the sound icon.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-338","question":"A PowerPoint deck plays linked video files kept in another folder. It must be carried to another computer so that everything still plays. Which option gathers the deck and its linked files together?","options":["Save As PowerPoint Show (.ppsx)","Package Presentation for CD","Save As PDF document","Compress Pictures"],"answer":1,"explanation":"Package Presentation for CD copies the presentation with its linked files into a folder or CD. A .ppsx only changes how the file opens and does not collect linked media.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-339","question":"In PowerPoint, one slide has text typed in its title and content placeholders and also some text inside a text box drawn with the Text Box tool. Which text appears in Outline view?","options":["Only the text inside the separately drawn text box","All the text on the slide, from every source","Only the text in the title and content placeholders","None of it, because Outline view shows thumbnails"],"answer":2,"explanation":"Outline view lists only text in the layout's title and body placeholders. Text in a manually added text box does not appear there, which is why placeholders are preferred.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-340","question":"In PowerPoint, a shape is set up so that a new slide opens as soon as the pointer moves over it during the show, without clicking. Which setting is used?","options":["Action Settings on the Mouse Click tab","Action Settings on the Mouse Over tab","A trigger set on the shape's own animation","A transition set to advance After a time"],"answer":1,"explanation":"Action Settings has two tabs: Mouse Click acts on a click, and Mouse Over acts when the pointer simply passes over the object.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-341","question":"In MS PowerPoint, which pair of shortcuts groups the selected objects and ungroups a group respectively?","options":["Ctrl + Shift + G and Ctrl + G","Ctrl + G and Ctrl + U","Ctrl + G and Ctrl + Shift + G","Alt + G and Alt + Shift + G"],"answer":2,"explanation":"Ctrl + G groups and Ctrl + Shift + G ungroups selected objects. Ctrl + U is underline.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-342","question":"In PowerPoint, the Oval tool is selected. Which key should be held while dragging so that the shape is drawn as a perfect circle?","options":["Shift","Ctrl","Alt","Tab"],"answer":0,"explanation":"Holding Shift keeps the width and height equal (a circle or square). Ctrl draws the shape outward from the centre, and Alt turns off snapping to the grid.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-343","question":"Five icons are placed roughly in a row on a PowerPoint slide. Which command makes the gaps between them exactly equal, keeping the first and last icons where they are?","options":["Align Center to the slide","Align Middle to the slide","Group, then Align Left","Distribute Horizontally"],"answer":3,"explanation":"Distribute Horizontally spaces three or more objects evenly between the outer two. Align Center and Align Middle line objects up along one axis but do not equalise gaps.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-344","question":"A PowerPoint slide uses the Title and Content arrangement, but the presenter wants two side-by-side content boxes on it instead. What should be changed for that slide?","options":["Its theme","Its transition","Its layout","Its slide size"],"answer":2,"explanation":"A layout decides which placeholders a slide has and where (for example Two Content). A theme controls colours, fonts and effects for the whole deck.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL"},
  {"id":"comp-ms-office-internet-345","question":"In PowerPoint, slide numbers must appear on every slide except the title slide. Which option does this?","options":["Insert > Header & Footer > Slide number with Don't show on title slide ticked","Insert > Slide Number on each slide, then delete it from the title slide each time","View > Slide Master > Different First Page ticked for the title layout","Design > Slide Size > Start numbering at 2 for the presentation"],"answer":0,"explanation":"The Header & Footer dialog has a Slide number box and a Don't show on title slide option. Different First Page is a Word header option, not a PowerPoint one.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-346","question":"Which PowerPoint feature runs the show and saves the presenter's voice narration, ink and laser-pointer gestures with the slide timings?","options":["Rehearse Timings","Record Slide Show","Custom Slide Show","Set Up Slide Show"],"answer":1,"explanation":"Record Slide Show captures narration, ink and pointer along with timings. Rehearse Timings records only how long each slide stays on screen.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-347","question":"An Excel chart is pasted into a PowerPoint deck as a LINKED object, and another copy is pasted as an EMBEDDED object. The Excel file's figures are then changed. What happens?","options":["The embedded chart updates to the new figures; the linked one keeps the old data","Both charts update, since both of them came from the same Excel file","Neither chart changes, since pasting breaks every tie to Excel","The linked chart can update to the new figures; the embedded one keeps the old data"],"answer":3,"explanation":"A linked object points to the source file and can be refreshed from it. An embedded object carries its own copy of the data inside the presentation and does not follow the source.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-348","question":"Up to how many copied items can the Office Clipboard (Home tab > Clipboard pane) hold at a time in MS Office applications?","options":["12","32","Only 1","24"],"answer":3,"explanation":"The Office Clipboard keeps up to 24 items; copying a 25th removes the oldest. The ordinary Windows clipboard paste (Ctrl + V) uses only the latest item.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-349","question":"In MS Office programs such as Word and Excel, what does pressing Ctrl + F1 do?","options":["Opens the Help window for the program","Opens the Print preview of the file","Shows or hides (collapses) the ribbon","Starts the spelling and grammar check"],"answer":2,"explanation":"Ctrl + F1 collapses or expands the ribbon. F1 alone opens Help, Ctrl + F2 shows print preview and F7 runs the spelling check.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-350","question":"In MS Office programs, what happens when the Alt key is pressed and released?","options":["Small letters (KeyTips) appear on the ribbon for keyboard access","The program switches to the next open window of the same file","The selected text is changed to the alternate font of the theme","The ribbon is hidden until the mouse is moved to the top again"],"answer":0,"explanation":"Pressing Alt shows KeyTips, letters you can type to open a tab and then a command (for example Alt, H for the Home tab), so the ribbon can be used without a mouse.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-351","question":"A Word file downloaded as an e-mail attachment opens with a yellow bar saying the file is read-only for safety until Enable Editing is clicked. Which Office feature is this?","options":["Restrict Editing","Protected View","Mark as Final","Compatibility Mode"],"answer":1,"explanation":"Protected View opens files from the internet or attachments in a read-only sandbox so that harmful content cannot run. Mark as Final is set by the author, not by the file's origin.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-352","question":"Which statement about AutoRecover in MS Office is correct?","options":["It saves the original file itself after every change, so Ctrl + S is never needed","It saves recovery copies at intervals but does not replace a normal save","It keeps every earlier version of the file permanently, even after a normal close","It works only for files that have been saved in the older .doc or .xls formats"],"answer":1,"explanation":"AutoRecover stores temporary recovery information (every 10 minutes by default) to restore work after a crash; if you close without saving, normal changes can still be lost.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-353","question":"Which of these is NOT a private IPv4 address?","options":["10.255.1.1","192.168.100.1","172.32.5.1","172.20.0.5"],"answer":2,"explanation":"The private ranges are 10.0.0.0 to 10.255.255.255, 172.16.0.0 to 172.31.255.255 and 192.168.0.0 to 192.168.255.255. 172.32.5.1 lies just outside the 172.16 to 172.31 block, so it is public.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-354","question":"A technician runs ping 127.0.0.1 on a computer and gets replies. What has this test checked?","options":["The default gateway router that connects the LAN to the internet","The DNS server set up by the internet service provider","The first computer on the same local area network","The computer's own TCP/IP software, without using the network"],"answer":3,"explanation":"127.0.0.1 is the loopback address: packets never leave the machine, so a reply only shows that its own TCP/IP stack works.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-355","question":"A Windows PC set to obtain an IP address automatically shows the address 169.254.23.7 and cannot reach the internet. What is the most likely reason?","options":["It got no reply from a DHCP server, so it gave itself an address","It has been given a public IP address directly by the ISP","It is using the loopback address to test its own network card","It is connected to a network that uses only IPv6 addresses"],"answer":0,"explanation":"Addresses in 169.254.0.0/16 are self-assigned (APIPA, link-local) when no DHCP server answers; they work only on the local link, not on the internet.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-356","question":"How many usable host addresses does an IPv4 subnet with prefix /26 provide?","options":["64","62","30","126"],"answer":1,"explanation":"A /26 leaves 32 - 26 = 6 host bits, so 2^6 = 64 addresses, minus the network and broadcast addresses, leaving 62 usable hosts.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-357","question":"In the network 192.168.10.0 with subnet mask 255.255.255.0, which is the broadcast address?","options":["192.168.10.0","192.168.10.254","192.168.10.255","192.168.10.1"],"answer":2,"explanation":"With a /24 mask the last octet is the host part. All host bits set to 1 gives the broadcast address .255; .0 is the network address and .1 to .254 are usable hosts.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-358","question":"Under classful IPv4 addressing, the address 150.12.4.9 belongs to which class?","options":["Class B","Class A","Class C","Class D"],"answer":0,"explanation":"The first octet decides the class: 1 to 126 is Class A, 128 to 191 Class B, 192 to 223 Class C and 224 to 239 Class D (multicast). 150 falls in Class B.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-359","question":"In what order are the four DHCP messages exchanged when a computer joins a network and gets an IP address?","options":["Request, Offer, Discover, Acknowledge","Discover, Offer, Request, Acknowledge","Discover, Request, Offer, Acknowledge","Offer, Discover, Request, Acknowledge"],"answer":1,"explanation":"DHCP follows DORA: the client broadcasts Discover, servers send Offer, the client Requests one offer, and the server Acknowledges it.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-360","question":"Which sequence of segments opens a TCP connection (the three-way handshake)?","options":["SYN, ACK, SYN-ACK","ACK, SYN-ACK, SYN","SYN, SYN-ACK, FIN","SYN, SYN-ACK, ACK"],"answer":3,"explanation":"The client sends SYN, the server replies SYN-ACK, and the client confirms with ACK. FIN is used to close a connection, not open it.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-361","question":"Which pair of applications usually relies on UDP rather than TCP?","options":["File transfer by FTP and remote login by SSH","Live video calls and DNS lookups","Sending mail by SMTP and reading it by IMAP","Web pages over HTTP/1.1 and file transfer by FTP"],"answer":1,"explanation":"UDP is connectionless and fast, suiting real-time voice or video and short DNS queries, where an occasional lost packet is better than a delay. FTP, SSH, SMTP, IMAP and HTTP/1.1 use TCP.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-362","question":"Match the networking device with the OSI layer it mainly works at: 1. Hub 2. Switch 3. Router; a. Network layer b. Physical layer c. Data link layer","options":["1-c, 2-b, 3-a","1-b, 2-a, 3-c","1-b, 2-c, 3-a","1-a, 2-c, 3-b"],"answer":2,"explanation":"A hub just repeats electrical signals (Physical), a switch forwards frames by MAC address (Data link), and a router forwards packets by IP address (Network).","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-363","question":"Which layer of the OSI model handles data translation, encryption and compression, so that both systems can understand the data format?","options":["Session layer","Application layer","Transport layer","Presentation layer"],"answer":3,"explanation":"The Presentation layer (layer 6) deals with format conversion, encryption and compression. The Session layer manages dialogues, and the Transport layer handles end-to-end delivery.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-364","question":"The ping command checks whether a host is reachable by sending echo request messages of which protocol?","options":["ICMP","ARP","SNMP","SMTP"],"answer":0,"explanation":"Ping sends ICMP Echo Request messages and waits for Echo Replies. ARP finds MAC addresses, SNMP manages network devices and SMTP sends e-mail.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-365","question":"On a Windows computer, which command shows each router (hop) that packets pass through on their way to a website?","options":["ipconfig","nslookup","tracert","netstat"],"answer":2,"explanation":"tracert (traceroute) lists every hop with its delay. ipconfig shows the PC's own IP settings, nslookup queries DNS, and netstat lists current connections.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk"},
  {"id":"comp-ms-office-internet-366","question":"Match the DNS record type with what it holds: 1. A 2. AAAA 3. MX 4. CNAME; a. an alias that points to another domain name b. the mail server for the domain c. an IPv6 address d. an IPv4 address","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a"],"answer":1,"explanation":"An A record maps a name to an IPv4 address and AAAA to an IPv6 address; MX names the mail server; CNAME makes one name an alias of another.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-367","question":"Match the service with its default port number: 1. DNS 2. DHCP server 3. SNMP 4. NTP; a. 123 b. 161 c. 53 d. 67","options":["1-c, 2-d, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-a, 4-b"],"answer":0,"explanation":"DNS uses port 53, a DHCP server listens on 67 (the client uses 68), SNMP uses 161 and NTP (time synchronisation) uses 123.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-368","question":"Classic FTP opens two TCP connections. Which default ports does it use for them (in active mode)?","options":["20 for control, 21 for data","22 for control, 21 for data","25 for control, 20 for data","21 for control, 20 for data"],"answer":3,"explanation":"FTP sends commands over the control connection on port 21 and, in active mode, transfers files over a data connection from port 20. Port 22 is SSH and 25 is SMTP.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-369","question":"Assertion (A): A net-banking site uses a session cookie to keep a customer logged in while moving from page to page. Reason (R): HTTP is a stateless protocol, so the server treats each request on its own unless something identifies the user.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because HTTP keeps no memory between requests, sites send a session ID in a cookie with every request to recognise the logged-in user. So R explains A.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-370","question":"A website's login form is sent using the HTTP GET method instead of POST. What is the main risk?","options":["GET requests can never be encrypted, even when the site uses HTTPS","GET can send only numbers, so the password must be numeric","The username and password become part of the URL, history and server logs","GET opens a separate TCP port for every field of the form"],"answer":2,"explanation":"GET adds form data to the URL as a query string, which is saved in browser history, bookmarks and logs. POST sends it in the request body; HTTPS encrypts both on the wire.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-371","question":"Eight branch routers are joined in a full mesh, each connected directly to every other. How many links are needed, and how many ports does each router use for them?","options":["56 links; 7 ports on each router","28 links; 7 ports on each router","28 links; 8 ports on each router","64 links; 8 ports on each router"],"answer":1,"explanation":"A full mesh of n devices needs n(n - 1)/2 = 8 × 7 / 2 = 28 links, and each device connects to the other n - 1 = 7. Counting 56 counts every link twice.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-372","question":"Which statement about a star topology LAN is correct?","options":["If any one cable breaks the whole LAN stops, but the central switch can fail safely","Data passes through every node in turn, so one failed node stops the whole ring","All nodes share one backbone cable, so a break in it splits the network in two","If the central switch fails the whole LAN stops, but one broken cable cuts off only one node"],"answer":3,"explanation":"In a star each node has its own cable to the central device, so a single cable affects one node, but the centre is a single point of failure. The other options describe ring and bus.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-373","question":"Match the communication with its transmission mode: 1. Walkie-talkie 2. Telephone call 3. FM radio broadcast; a. Simplex b. Half-duplex c. Full-duplex","options":["1-b, 2-c, 3-a","1-c, 2-b, 3-a","1-a, 2-c, 3-b","1-b, 2-a, 3-c"],"answer":0,"explanation":"A walkie-talkie works both ways but one at a time (half-duplex), a phone call both ways at once (full-duplex), and FM radio only one way (simplex).","difficulty":"moderate","source":"SSC CGL · SBI Clerk"},
  {"id":"comp-ms-office-internet-374","question":"Match the technology with its IEEE standard: 1. Wired Ethernet 2. Wi-Fi 3. Bluetooth; a. 802.11 b. 802.3 c. 802.15","options":["1-a, 2-b, 3-c","1-b, 2-a, 3-c","1-b, 2-c, 3-a","1-c, 2-a, 3-b"],"answer":1,"explanation":"Ethernet is IEEE 802.3, wireless LAN (Wi-Fi) is 802.11, and Bluetooth was standardised under the personal area network group 802.15.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-375","question":"Which statement about a MAC address is correct?","options":["It is 32 bits long and written as 4 decimal numbers","It is 48 bits long and written as 6 decimal numbers","It is 48 bits long and written as 12 hexadecimal digits","It is 128 bits long and written as 32 hexadecimal digits"],"answer":2,"explanation":"A MAC address is a 48-bit hardware address, written as six pairs of hex digits such as 00:1A:2B:3C:4D:5E. 32 bits in dotted decimal describes IPv4, and 128 bits IPv6.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-376","question":"An officer travelling on a hotel's public Wi-Fi must open the bank's internal applications safely. Which technology builds an encrypted tunnel to the bank's network across the internet?","options":["NAT (Network Address Translation)","DHCP (Dynamic Host Configuration)","DNS (Domain Name System)","VPN (Virtual Private Network)"],"answer":3,"explanation":"A VPN encrypts all traffic between the device and the bank's VPN gateway, so others on the hotel Wi-Fi cannot read it. NAT, DHCP and DNS handle addressing and naming, not encryption.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-377","question":"Which network device only regenerates a weakened signal so that a cable can run further, without reading any address in the data?","options":["Bridge","Repeater","Switch","Router"],"answer":1,"explanation":"A repeater works at the Physical layer and just amplifies or regenerates signals. A bridge and a switch forward by MAC address, and a router by IP address.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-378","question":"Two office buildings are linked by cable that must pass next to heavy electrical machinery. Why is optical fibre the best choice?","options":["It carries light, so electrical interference does not affect it","It carries larger currents, so the signal is never weakened","It is cheaper and easier to join than copper twisted pair","It needs no repeaters or amplifiers over any distance at all"],"answer":0,"explanation":"Optical fibre sends data as light pulses through glass, so it is immune to electromagnetic interference. It is usually costlier to install and join, and long links still need amplification.","difficulty":"moderate","source":"SSC CGL · SBI Clerk"},
  {"id":"comp-ms-office-internet-379","question":"When a browser opens an HTTPS banking site, how are symmetric and asymmetric encryption used?","options":["Symmetric encryption sets up the keys, then asymmetric encryption protects all the data","Only asymmetric encryption is used, because it is faster than symmetric for bulk data","Asymmetric keys set up a shared session key, then symmetric encryption protects the data","Only symmetric encryption is used, with a key printed on the site's certificate"],"answer":2,"explanation":"Public-key (asymmetric) methods are slow, so TLS uses them only to authenticate the server and agree a session key; the bulk data is then encrypted with a fast symmetric cipher such as AES.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-380","question":"A well-run website stores a hash of each password, not the password itself. Why does this protect users if the database is stolen?","options":["A hash is encrypted with the user's own key, which the thief cannot get","A hash is one-way, so the password cannot simply be decrypted from it","A hash changes every day, so a stolen copy expires within a few hours","A hash is stored on a separate server that attackers cannot reach"],"answer":1,"explanation":"A cryptographic hash cannot be reversed; at login the site hashes the typed password and compares the results. Attackers can only guess passwords and hash each guess.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-381","question":"Before hashing each password, a website adds a random value (a salt) that is different for every user. Which attack does this mainly defeat?","options":["Using precomputed rainbow tables of hashes","Phishing e-mails that ask for the password","Keyloggers that record the typed password","Shoulder surfing while the password is typed"],"answer":0,"explanation":"A unique salt makes the same password hash differently for each user, so a precomputed table of hashes is useless. Salting cannot stop a password being captured before it is hashed.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-382","question":"An attacker tries passwords such as password123, india@2020 and qwerty taken from a list of common words, rather than every possible combination. What is this called, and what stops it on a login page?","options":["A brute-force attack, stopped by turning off cookies in the browser","A credential-stuffing attack, stopped by a shorter session timeout","A rainbow-table attack, stopped by salting the stored hashes","A dictionary attack, stopped by a lockout after a few failures"],"answer":3,"explanation":"A dictionary attack tries likely words and leaked passwords; brute force tries every combination. Lockouts or delays after failed logins limit both kinds of online guessing.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-383","question":"On a café's free Wi-Fi, an attacker places himself between users and the router, quietly reading and changing the traffic passing through. What is this attack called?","options":["Man-in-the-middle attack","Denial-of-service attack","Brute-force attack","Logic bomb attack"],"answer":0,"explanation":"In a man-in-the-middle attack the attacker relays and can alter traffic between two parties. HTTPS with valid certificates (and not ignoring certificate warnings) defends against it.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-384","question":"An outsider without an ID card walks into a bank's server room by following closely behind an employee who opened the door with his own card. This is called:","options":["Shoulder surfing","Tailgating","Dumpster diving","Pharming"],"answer":1,"explanation":"Tailgating (piggybacking) is physical entry by following an authorised person. Shoulder surfing is watching someone type, and dumpster diving is searching thrown-away papers.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-385","question":"USB drives labelled Salary Revision 2024 are left in a bank's car park. An employee plugs one in out of curiosity, and malware installs itself. Which social engineering trick is this?","options":["Pretexting","Tailgating","Baiting","Vishing"],"answer":2,"explanation":"Baiting uses a tempting item, such as a free download or a found USB drive, to make the victim run malware. Pretexting relies on a made-up story told to the victim.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk"},
  {"id":"comp-ms-office-internet-386","question":"A caller says he is from the bank's internal audit team doing a surprise check, gives the branch manager's name correctly, and asks a clerk to read out a customer's account details 'for verification'. Which technique is mainly used?","options":["Baiting","Tailgating","Typosquatting","Pretexting"],"answer":3,"explanation":"Pretexting builds a believable invented scenario (here an audit) with insider details to get information. Baiting offers a lure, and typosquatting uses look-alike web addresses.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-387","question":"Attackers who want to break into a group of banks infect a banking-industry news website that the banks' staff visit often, and wait for staff to get infected from it. This is called:","options":["A watering hole attack","A whaling attack on executives","A salami attack on accounts","A smurf attack on routers"],"answer":0,"explanation":"A watering hole attack compromises a site that the target group trusts and visits. Whaling targets senior executives by e-mail, and a salami attack skims tiny amounts.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-388","question":"A fraudster registers the web address examp1ebank.com (with the digit 1 in place of the letter l) to catch customers who mistype or misread the real address. This is called:","options":["Pharming","Typosquatting","Spoofing the MAC address","Cryptojacking"],"answer":1,"explanation":"Typosquatting registers look-alike or misspelt domain names. Pharming instead corrupts DNS so that even the correctly typed real address leads to a fake site.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk"},
  {"id":"comp-ms-office-internet-389","question":"An attacker steals the session cookie of a customer who is logged in to net banking and uses it to act as that customer without knowing the password. This is called:","options":["Credential stuffing","Password spraying","DNS spoofing","Session hijacking"],"answer":3,"explanation":"Session hijacking reuses a valid session token to take over a logged-in session. Credential stuffing and password spraying both try passwords to log in.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-390","question":"A Word file received by e-mail asks the user to click Enable Content. Once clicked, code inside the file downloads malware. What kind of virus is this?","options":["Boot sector virus","Polymorphic worm","Macro virus","Firmware rootkit"],"answer":2,"explanation":"A macro virus is written in the macro language of a document (such as VBA) and runs when macros are enabled. This is why Office blocks macros in files from the internet by default.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk"},
  {"id":"comp-ms-office-internet-391","question":"Which kind of virus changes its own code every time it infects a new file, so that each copy looks different to signature-based antivirus?","options":["Boot sector virus","Macro virus","Resident virus","Polymorphic virus"],"answer":3,"explanation":"A polymorphic virus mutates (often by re-encrypting itself with a new key) on each infection, so no single signature matches all copies. Behaviour-based detection is needed.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-392","question":"A virus infects both the boot sector of the disk and executable program files, so it returns unless both are cleaned. It is called a:","options":["Polymorphic virus","Macro virus","Multipartite virus","Companion virus"],"answer":2,"explanation":"A multipartite virus spreads in more than one way, typically through the boot sector and through program files, which makes it hard to remove fully.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-393","question":"While browsing, a flashing pop-up claims 'Your PC has 37 viruses! Buy this cleaner now', though nothing is wrong. Buying it installs malware. This is:","options":["Spyware","Scareware","Ransomware","Adware"],"answer":1,"explanation":"Scareware frightens users with fake alerts into buying or installing harmful software. Ransomware locks real files, spyware secretly watches, and adware just pushes ads.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-394","question":"Arrange these malware outbreaks in chronological order: 1. WannaCry ransomware 2. Morris worm 3. ILOVEYOU e-mail worm 4. Brain virus (the first IBM PC virus)","options":["4, 2, 3, 1","2, 4, 3, 1","4, 3, 2, 1","2, 3, 4, 1"],"answer":0,"explanation":"Brain appeared in 1986, the Morris worm in 1988, ILOVEYOU in 2000 and WannaCry in 2017.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-395","question":"How does a stateful inspection firewall differ from a simple packet-filtering firewall?","options":["It checks only the source and destination addresses in each packet header","It tracks open connections and allows only replies that belong to them","It scans the text of every e-mail for spelling and grammar","It encrypts all packets that leave the network by default"],"answer":1,"explanation":"A packet filter judges each packet alone by header rules. A stateful firewall keeps a table of active connections, so incoming packets are allowed only as part of an established session.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-396","question":"What is the main difference between an IDS and an IPS on a bank's network?","options":["An IDS blocks attacks in real time; an IPS only writes them into a log file","An IDS works only on wireless networks; an IPS works only on wired ones","An IDS checks passwords at login; an IPS checks IP addresses at the router","An IDS detects and alerts on attacks; an IPS can also block them in real time"],"answer":3,"explanation":"An Intrusion Detection System monitors and raises alarms; an Intrusion Prevention System sits in the traffic path and can drop malicious packets automatically.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-397","question":"A bank keeps its public website server in a separate network zone between two firewalls, so that a hacked web server cannot reach the internal core banking network directly. This zone is called a:","options":["VLAN (virtual LAN)","Honeynet (decoy network)","DMZ (demilitarised zone)","Extranet (partner network)"],"answer":2,"explanation":"A DMZ holds internet-facing servers apart from the internal LAN, with firewall rules limiting what it can reach. A honeynet is a decoy built to study attackers.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-398","question":"A cashier's login can post cash transactions but cannot change interest rates or create users. Which security principle does this follow?","options":["Least privilege","Defence in depth","Non-repudiation","Security through obscurity"],"answer":0,"explanation":"The principle of least privilege gives each user only the access the job needs, limiting harm from mistakes or a stolen login. Non-repudiation means a sender cannot deny an action.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-399","question":"A bank makes its fingerprint scanners stricter so that they match more closely. What usually happens to the False Acceptance Rate (FAR) and the False Rejection Rate (FRR)?","options":["FAR rises but FRR falls","Both FAR and FRR fall","FAR falls but FRR rises","Both FAR and FRR rise"],"answer":2,"explanation":"A stricter threshold lets fewer impostors in (lower FAR) but rejects more genuine users (higher FRR). The two trade off; the point where they are equal is the crossover error rate.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-400","question":"A branch takes a full backup on Sunday and a DIFFERENTIAL backup each night from Monday to Thursday. Its server crashes on Friday morning. Which backups are needed to restore all the data?","options":["Sunday's full and all four differentials","Sunday's full and Thursday's differential","Only Thursday's differential backup","Only Sunday's full backup"],"answer":1,"explanation":"Each differential holds every change since the last FULL backup, so the latest one plus the full is enough. With incremental backups, every one since the full would be needed.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-401","question":"Which of these statements about UPI safety are correct? I. A UPI PIN is never needed to receive money into your own account. II. Scanning a QR code is needed to receive money from a buyer. III. A genuine bank never asks a customer to share an OTP or PIN.","options":["I and II only","II and III only","I, II and III","I and III only"],"answer":3,"explanation":"Receiving money needs no PIN and no QR scan by the receiver; fraudsters send collect requests or QR codes to 'pay' victims, which actually debit them. Banks never ask for OTP or PIN.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-402","question":"A customer gets a link: https://examplebank.in.secure-login.xyz/kyc. Which domain does this link actually lead to?","options":["secure-login.xyz","examplebank.in","in.secure-login","kyc.examplebank.in"],"answer":0,"explanation":"The registered domain is read from the right, just before the path: secure-login.xyz. examplebank.in is only a subdomain label chosen by the fraudster to look genuine.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-403","question":"A website shows the padlock icon and https:// in the address bar. What does this prove?","options":["The site is the genuine site of the bank it claims to be","The connection is encrypted to whoever owns that domain","The site has been checked and approved by the RBI","The site contains no malware or phishing content"],"answer":1,"explanation":"The padlock shows TLS encryption to a server holding a valid certificate for that domain. Phishing sites can get certificates too, so the domain name itself must be checked.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-404","question":"A bank digitally signs a PDF statement but does not encrypt it. Which security service does the digital signature NOT give?","options":["Confidentiality","Integrity","Authentication","Non-repudiation"],"answer":0,"explanation":"A digital signature proves who signed (authentication), shows any change (integrity) and stops the signer denying it (non-repudiation). Keeping the content secret needs encryption.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-405","question":"Asha sends an e-mail To: Ravi, Cc: Meena and Bcc: Tarun. Tarun clicks Reply All. Who receives Tarun's reply?","options":["Asha, Ravi and Meena, who now learn that Tarun had a copy","Only Asha, because a Bcc recipient cannot reply to everyone","Asha and Ravi only, because Cc recipients are left out","Asha, Ravi, Meena and Tarun himself, as a Bcc copy"],"answer":0,"explanation":"Reply All goes to the sender and every visible To and Cc address, so Ravi and Meena get it and discover Tarun was blind-copied. This is why Bcc recipients should usually reply only to the sender.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-406","question":"Which of these is a validly formed e-mail address?","options":["ravi kumar@bank.in","ravi.k@bank.co.in","ravi@@mail.bank.in","www.ravi.bank.in"],"answer":1,"explanation":"An address needs one @ separating the user name from the domain, and no spaces. A dot inside the user name and a domain such as bank.co.in are allowed.","difficulty":"moderate","source":"SSC CHSL · SBI Clerk"},
  {"id":"comp-ms-office-internet-407","question":"An e-mail shows From: Customer Care <care@examplebank.in>, but its Reply-To field is set to an address at another domain. What happens if the reader simply clicks Reply?","options":["The reply goes to the From address, since Reply-To is ignored","The reply goes to both addresses, as if Reply All was clicked","The reply is blocked by the mail server as a spoofed message","The reply goes to the Reply-To address, not to the From address"],"answer":3,"explanation":"Mail programs send a reply to the Reply-To address when one is set. Fraudsters use this so that replies to a genuine-looking From address reach them instead.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-408","question":"For what is TCP port 587 normally used in e-mail?","options":["A mail client downloading messages from its server with POP3","A mail client reading messages from its server over IMAP with TLS","A mail client submitting outgoing mail, with login","Mail servers passing messages to each other without any login"],"answer":2,"explanation":"Port 587 is the message submission port, where users' mail programs send outgoing mail with authentication. Server-to-server relay uses port 25, POP3 uses 110 and IMAP over TLS 993.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-409","question":"An e-mail sent to a misspelt address comes back automatically with a message saying it could not be delivered. This returned message is called a:","options":["Read receipt from the receiver","Non-delivery report (bounce)","Out-of-office auto-reply","Spam complaint report"],"answer":1,"explanation":"When the receiving server cannot deliver a message, for example because the mailbox does not exist, a non-delivery report or bounce is sent back to the sender.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL"},
  {"id":"comp-ms-office-internet-410","question":"A user writes a message in a desktop mail program and clicks Send while the laptop has no internet connection. Where does the message wait until it can be sent?","options":["Outbox","Drafts","Sent Items","Junk E-mail"],"answer":0,"explanation":"A message that has been sent but not yet delivered to the mail server waits in the Outbox; it moves to Sent Items after it leaves. Drafts holds messages not yet sent.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk"},
  {"id":"comp-ms-office-internet-411","question":"Which statement about webmail (such as reading mail in a browser) and a desktop mail client is correct?","options":["Webmail uses POP3 to download every message to the browser; a desktop client uses only HTTPS","Webmail needs no mail server at all, as messages travel directly between browsers","Webmail stores all messages only on the user's own computer, never on a server","Webmail uses HTTPS to the provider; a desktop client uses IMAP and SMTP"],"answer":3,"explanation":"In webmail the browser is just a web client speaking HTTP(S) to the provider's web servers, which hold the mailbox. A desktop client talks mail protocols (IMAP/POP3 to read, SMTP to send).","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-412","question":"A browser keeps showing an old version of a web page even after F5 is pressed. Which shortcut forces a full reload that ignores the cached copy?","options":["Alt + F5","Shift + F10","Ctrl + F5","Ctrl + F4"],"answer":2,"explanation":"Ctrl + F5 (a hard refresh) reloads the page and fetches files from the server again instead of the browser cache. Ctrl + F4 closes the current tab.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-413","question":"Which shortcuts open a new private (incognito) window in Google Chrome and in Mozilla Firefox respectively?","options":["Ctrl + Shift + P and Ctrl + Shift + N","Ctrl + Shift + N and Ctrl + Shift + P","Ctrl + Shift + N in both browsers","Ctrl + Shift + T and Ctrl + Shift + P"],"answer":1,"explanation":"Chrome uses Ctrl + Shift + N for an Incognito window and Firefox uses Ctrl + Shift + P for a Private Window. Ctrl + Shift + T reopens a closed tab.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-414","question":"A user accidentally closes a browser tab. Which shortcut reopens the most recently closed tab in common browsers?","options":["Ctrl + T","Ctrl + Shift + W","Ctrl + Z","Ctrl + Shift + T"],"answer":3,"explanation":"Ctrl + Shift + T restores the last closed tab. Ctrl + T opens a new blank tab and Ctrl + Shift + W closes the whole window.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-415","question":"In common web browsers, which shortcut moves the cursor to the address bar and selects the URL so that a new address can be typed?","options":["Ctrl + L","Ctrl + D","Ctrl + H","Ctrl + J"],"answer":0,"explanation":"Ctrl + L (also Alt + D or F6) jumps to the address bar. Ctrl + D bookmarks the page, Ctrl + H opens history and Ctrl + J opens downloads.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-416","question":"In a Google search, which query finds pages that have the phrase annual report in their page title?","options":["inurl:\"annual report\"","site:\"annual report\"","intitle:\"annual report\"","filetype:\"annual report\""],"answer":2,"explanation":"intitle: limits results to words in the page title. inurl: looks in the web address, site: restricts results to a domain and filetype: to a file format.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-417","question":"Which of these best describes Web 2.0?","options":["Read-only pages put up by site owners just for visitors to view and download","Sites where users create and share content, like blogs and wikis","A newer, faster second internet that runs only over IPv6 addresses","The browser-free network of sensors and smart devices that talk to each other"],"answer":1,"explanation":"Web 2.0 refers to the interactive, user-generated web of blogs, wikis and social networks, unlike the mostly read-only Web 1.0. Connected sensors describe the Internet of Things.","difficulty":"moderate","source":"SSC CGL · SBI Clerk"},
  {"id":"comp-ms-office-internet-418","question":"A bank's page that shows each logged-in customer their own balance and recent transactions is an example of a:","options":["Dynamic web page, built by the server for each request","Static web page, stored on the server as one fixed HTML file","Web portal page, shared alike by every visitor","Cached web page, saved in the browser in advance"],"answer":0,"explanation":"A dynamic page is generated on the fly, often from a database, so its content differs per user and per visit. A static page is the same fixed file for everyone.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-419","question":"In the web address www.mail.example.co.in, which part is the top-level domain?","options":[".co.in","example","www",".in"],"answer":3,"explanation":"Domain names are read from the right, and the top-level domain is the last label, .in (India's country-code TLD). .co is a second-level domain under it, and example is registered under .co.in.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-420","question":"A search engine program that automatically visits web pages and follows their links to collect pages for its index is called a:","options":["Web hosting server","Domain name server","Web crawler","Browser extension"],"answer":2,"explanation":"Crawlers (spiders or bots) move from link to link fetching pages, which the search engine then indexes. A web server only serves pages when asked.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL"},
  {"id":"comp-ms-office-internet-421","question":"Which organisation coordinates the internet's domain name system and the worldwide allocation of IP address blocks?","options":["ICANN","W3C","IEEE","ITU"],"answer":0,"explanation":"ICANN (through the IANA functions) oversees the DNS root and IP address allocation to regional registries. W3C sets web standards and IEEE sets standards such as Ethernet and Wi-Fi.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-422","question":"Which body develops web standards such as CSS and the Web Content Accessibility Guidelines (WCAG)?","options":["Internet Corporation for Assigned Names and Numbers","Institute of Electrical and Electronics Engineers","World Wide Web Consortium (W3C)","International Organization for Standardization"],"answer":2,"explanation":"The W3C, founded by Tim Berners-Lee, publishes web standards like CSS and WCAG. ICANN manages names and numbers, and IEEE sets networking standards such as 802.11.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-423","question":"Sections 66A to 66F, covering offences such as identity theft and cyber terrorism, were added to the Information Technology Act, 2000 by:","options":["The original Information Technology Act, 2000 itself","The Information Technology (Amendment) Act, 2008","The Digital Personal Data Protection Act, 2023","The Indian Penal Code (Amendment) Act, 2005"],"answer":1,"explanation":"The IT (Amendment) Act, 2008, in force from 2009, inserted Sections 66A to 66F among other changes. The original 2000 Act had only a single, general Section 66.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-424","question":"India's Information Technology Act, 2000 was based on which international model?","options":["Budapest Convention on Cybercrime, 2001","EU General Data Protection Regulation, 2016","OECD Guidelines on Privacy Protection, 1980","UNCITRAL Model Law on Electronic Commerce, 1996"],"answer":3,"explanation":"The IT Act gave legal recognition to electronic records following the UN General Assembly's adoption of the UNCITRAL Model Law on Electronic Commerce (1996). India has not joined the Budapest Convention.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-425","question":"In India, which authority licenses and regulates the Certifying Authorities that issue digital signature certificates under the IT Act?","options":["Indian Computer Emergency Response Team","Telecom Regulatory Authority of India","Controller of Certifying Authorities (CCA)","Unique Identification Authority of India"],"answer":2,"explanation":"The Controller of Certifying Authorities, appointed under the IT Act, licenses CAs and runs the root certifying authority. CERT-In handles cyber security incidents.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-426","question":"Under the First Schedule of the Information Technology Act, 2000, the Act does NOT apply to which of these, so it cannot be validly made as an electronic record?","options":["A will","A purchase order for goods","An income tax return","An e-mail giving notice of a meeting"],"answer":0,"explanation":"The First Schedule excludes wills, trusts, powers of attorney, negotiable instruments other than cheques, and contracts for the sale of immovable property from the Act.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-427","question":"In 2017 the Cyber Appellate Tribunal set up under the IT Act was merged into which body?","options":["National Company Law Appellate Tribunal","Central Administrative Tribunal, Principal Bench at Delhi","Securities Appellate Tribunal","Telecom Disputes Settlement and Appellate Tribunal"],"answer":3,"explanation":"The Finance Act, 2017 merged the Cyber Appellate Tribunal into the TDSAT, which now hears appeals under the IT Act.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-428","question":"A citizen in India wants to file a complaint about online financial fraud through the government's national online portal for cyber crime. Which website is it?","options":["cert-in.org.in","cybercrime.gov.in","digitalindia.gov.in","uidai.gov.in"],"answer":1,"explanation":"The National Cyber Crime Reporting Portal, cybercrime.gov.in, takes complaints from the public (with the 1930 helpline for financial fraud). CERT-In handles security incidents, not public crime complaints.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-429","question":"Match the section of the IT Act, 2000 with its subject: 1. Section 65 2. Section 69A 3. Section 72 4. Section 79; a. exemption of intermediaries from liability in certain cases b. tampering with computer source documents c. breach of confidentiality and privacy d. power to block public access to information","options":["1-b, 2-c, 3-d, 4-a","1-d, 2-b, 3-c, 4-a","1-b, 2-d, 3-a, 4-c","1-b, 2-d, 3-c, 4-a"],"answer":3,"explanation":"Section 65 punishes tampering with source code, 69A lets the government block websites (upheld in Shreya Singhal), 72 covers breach of confidentiality, and 79 is the intermediary safe harbour.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-430","question":"What does the Excel formula =LEFT(\"Mumbai\", 3) & RIGHT(\"Pune\", 2) return?","options":["Mumpu","baine","Mumne","Mune"],"answer":2,"explanation":"LEFT(\"Mumbai\", 3) gives Mum and RIGHT(\"Pune\", 2) gives the last two letters, ne; & joins them into Mumne.","difficulty":"moderate","source":"SSC CGL · SBI Clerk"},
  {"id":"comp-ms-office-internet-431","question":"In Excel, A1:A6 contain North, South, (blank), East, North, (blank). What does =COUNTIF(A1:A6, \"<>North\") return?","options":["2","3","6","4"],"answer":3,"explanation":"\"<>North\" counts every cell not equal to North, and that includes empty cells: South, East and the two blanks give 4. Counting only non-blank cells would give 2.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-432","question":"In Excel, A1 = Ram, A2 = 25, A3 is blank, A4 = Sita and A5 = TRUE. What does =COUNTIF(A1:A5, \"*\") return?","options":["4","2","3","5"],"answer":1,"explanation":"The wildcard \"*\" matches any TEXT value only, so it counts Ram and Sita. The number 25, the logical TRUE and the blank cell are not text.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-433","question":"In Excel, A1:A5 contain 10, 0, 20, 0 and 30. What does =AVERAGEIF(A1:A5, \"<>0\") return?","options":["20","12","15","60"],"answer":0,"explanation":"Only the non-zero values 10, 20 and 30 are averaged: 60 / 3 = 20. A plain AVERAGE would include the zeros and give 60 / 5 = 12.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-434","question":"A2:A6 contain North, South, North, East, North and B2:B6 contain 100, 200, 300, 400, 500. What does =SUMPRODUCT((A2:A6=\"North\")*(B2:B6)) return?","options":["1500","900","3","600"],"answer":1,"explanation":"(A2:A6=\"North\") gives 1 for North rows and 0 for others, so only 100 + 300 + 500 = 900 survive the multiplication. 3 would be a count of North rows.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-435","question":"In Excel, A1:C3 hold 10, 20, 30 in row 1; 40, 50, 60 in row 2; and 70, 80, 90 in row 3. What does =OFFSET(A1, 2, 1) return?","options":["60","40","50","80"],"answer":3,"explanation":"OFFSET moves 2 rows down and 1 column right from A1, reaching B3, which holds 80. Swapping the row and column offsets would wrongly reach C2 (60).","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-436","question":"In Excel, A1:C3 hold 10, 20, 30 in row 1; 40, 50, 60 in row 2; and 70, 80, 90 in row 3. What does =INDIRECT(\"C\" & ROW(A2)) return?","options":["60","40","30","#REF!"],"answer":0,"explanation":"ROW(A2) is 2, so the text built is \"C2\", and INDIRECT turns that text into a real reference to C2, which holds 60.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-437","question":"What does the Excel formula =ROW(C7) + COLUMN(C7) return?","options":["8","9","10","73"],"answer":2,"explanation":"ROW(C7) is 7 and COLUMN(C7) is 3, because C is the third column, so the sum is 10.","difficulty":"moderate","source":"SSC CGL · SBI Clerk"},
  {"id":"comp-ms-office-internet-438","question":"What does the Excel formula =ADDRESS(2, 3) return?","options":["$B$3","$C$2","C2","B3"],"answer":1,"explanation":"ADDRESS takes the row number first and then the column number, and by default returns an absolute reference as text: row 2, column 3 is $C$2.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-439","question":"In Excel, A1:A4 contain 0, 40, 60, 80 and B1:B4 contain F, C, B, A. What does =VLOOKUP(-5, A1:B4, 2, TRUE) return?","options":["#N/A","F","A","#VALUE!"],"answer":0,"explanation":"An approximate VLOOKUP finds the largest value not greater than the lookup value. Nothing in the column is less than or equal to -5, so it returns #N/A.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-440","question":"In Excel, cell A1 looks empty but actually contains a single space typed by mistake. What does =IF(A1=\"\", \"Empty\", \"Filled\") return?","options":["Empty","#VALUE!","Filled","TRUE"],"answer":2,"explanation":"A space is a character, so A1 is not equal to the empty string \"\" and the formula returns Filled. Such hidden spaces also upset COUNTBLANK and lookups.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-441","question":"What does the Excel formula =HOUR(\"14:45\") + MINUTE(\"14:45\") return?","options":["14.75","47","#VALUE!","59"],"answer":3,"explanation":"Excel converts the text \"14:45\" to a time; HOUR gives 14 and MINUTE gives 45, and their sum is 59. Using 2 for 2 PM would give 47.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-442","question":"What does the Excel formula =TIME(10, 90, 0) show when formatted as a time?","options":["10:30 AM","12:00 PM","#NUM!","11:30 AM"],"answer":3,"explanation":"TIME carries extra minutes into hours, so 90 minutes becomes 1 hour 30 minutes, giving 11:30 AM. Similarly, DATE carries extra months into years.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-443","question":"What does the Excel formula =(\"18:00\" - \"09:30\") * 24 return?","options":["8.5","8.3","0.35","#VALUE!"],"answer":0,"explanation":"Excel converts both time texts to fractions of a day; their difference is 8 h 30 min, and multiplying by 24 converts it to hours: 8.5. Without × 24 the result would be about 0.35.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-444","question":"Which statement about the Excel functions =TODAY() and =NOW() is correct?","options":["TODAY gives the date and time and NOW gives the time only; neither ever updates","Both give the date and the time, but only NOW updates when the sheet recalculates","TODAY gives the date only and NOW gives date and time; both update on recalculation","Both are fixed at the moment the formula is typed, like Ctrl + ; and Ctrl + Shift + ;"],"answer":2,"explanation":"TODAY returns the current date and NOW the current date and time; both are volatile and refresh on recalculation. Ctrl + ; and Ctrl + Shift + ; type fixed values instead.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk"},
  {"id":"comp-ms-office-internet-445","question":"5 January 2024 was a Friday. What date does =WORKDAY(DATE(2024, 1, 5), 3) return in Excel (no holidays given)?","options":["8 January 2024","10 January 2024","9 January 2024","11 January 2024"],"answer":1,"explanation":"WORKDAY skips weekends: from Friday 5 January, the next three working days are Monday 8, Tuesday 9 and Wednesday 10 January.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-446","question":"What does the Excel formula =NPV(10%, 110, 121) return?","options":["220","231","200","210"],"answer":2,"explanation":"NPV discounts the first value by one period and the second by two: 110/1.1 + 121/1.21 = 100 + 100 = 200. Treating the first value as today's money would wrongly give 220.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-447","question":"A machine costs ₹10,000, has a salvage value of ₹1,000 and a life of 5 years. What does the Excel formula =SLN(10000, 1000, 5) return?","options":["2000","1800","2200","9000"],"answer":1,"explanation":"SLN gives straight-line depreciation per year: (cost - salvage) / life = 9000 / 5 = 1800. Ignoring the salvage value would give 2000.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-448","question":"What does the Excel formula =ROUND(5/3, 2) * 3 return?","options":["5.01","5","4.98","5.1"],"answer":0,"explanation":"5/3 = 1.6667, which ROUND makes 1.67, and 1.67 × 3 = 5.01. Doing the maths exactly gives 5, truncating to 1.66 gives 4.98, and rounding to one decimal (1.7) gives 5.1; rounding before multiplying is a classic error in tax and percentage sheets.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-449","question":"In Excel, A1:A6 contain 35, 40, 55, 60, 72 and 48. What does =COUNTIFS(A1:A6, \">=40\", A1:A6, \"<=60\") return?","options":["2","6","3","4"],"answer":3,"explanation":"COUNTIFS needs both conditions, so it counts values from 40 to 60 inclusive: 40, 55, 60 and 48. Using strict > and < would leave only 55 and 48.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-450","question":"In Excel, A1:A6 contain 12, 58, 33, 71, 50, 49 and B1 = 50. What do =SUMIF(A1:A6, \">\"&B1) and =SUMIF(A1:A6, \">B1\") return respectively?","options":["129 and 129","179 and 0","0 and 129","129 and 0"],"answer":3,"explanation":"\">\"&B1 builds the criterion \">50\", adding 58 + 71 = 129. Inside quotes, \">B1\" compares with the text B1, which no number matches, so the second gives 0.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-451","question":"A1 holds last year's sales (80) and B1 this year's sales (100). Which formula, formatted as a percentage, gives the percentage increase?","options":["=(B1-A1)/B1","=(B1-A1)/A1","=B1/A1-100","=(A1-B1)/A1"],"answer":1,"explanation":"Increase is measured on the old value: (100 - 80)/80 = 25%. Dividing by the new value gives 20%, and B1/A1 - 1 (not - 100) would also work.","difficulty":"moderate","source":"SSC CGL · SBI Clerk"},
  {"id":"comp-ms-office-internet-452","question":"15 August 2024 was a Thursday. What does =TEXT(DATE(2024, 8, 15), \"dddd\") return?","options":["Thu","Wednesday","Thursday","15"],"answer":2,"explanation":"In a TEXT format, dddd gives the full weekday name and ddd the short name (Thu); dd would give the day number.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-453","question":"What does the Excel formula =TEXT(0.5, \"hh:mm\") return?","options":["12:00","00:30","05:00","00:05"],"answer":0,"explanation":"Excel stores time as a fraction of a day, so 0.5 is half a day, 12 hours, and the hh:mm format shows 12:00.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-454","question":"What does the Excel formula =LEN(TEXT(1234.5, \"#,##0.00\")) return?","options":["6","8","7","10"],"answer":1,"explanation":"TEXT returns the string 1,234.50, which has 8 characters including the comma and decimal point. LEN of the plain number 1234.5 is 6, forgetting the thousands comma gives 7, and counting the format's quote marks as characters gives 10.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-455","question":"In MS Word, the shortcuts Ctrl + 1, Ctrl + 2 and Ctrl + 5 set the line spacing of a paragraph to:","options":["1, 2 and 5 lines respectively","single, 1.5 and double lines respectively","single, double and 1.5 lines respectively","double, single and 1.5 lines respectively"],"answer":2,"explanation":"Ctrl + 1 gives single spacing, Ctrl + 2 double spacing and Ctrl + 5 one-and-a-half (1.5) spacing; the 5 stands for .5, not five lines.","difficulty":"moderate","source":"SSC CGL · SBI Clerk"},
  {"id":"comp-ms-office-internet-456","question":"In MS Word, what happens when Ctrl + M is pressed twice with the cursor in a paragraph?","options":["Only the first line of the paragraph is indented by two tab stops","The left indent of the whole paragraph moves two tab-stop steps right","A hanging indent two tab-stop steps deep is applied to the paragraph","Two tab characters are typed in front of the first word of the paragraph"],"answer":1,"explanation":"Ctrl + M increases the left indent of the entire paragraph by one step each time (Ctrl + Shift + M reduces it). Ctrl + T is the hanging indent shortcut.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-457","question":"In MS Word, what does Alt + Shift + Up Arrow do when the cursor is in a paragraph?","options":["Moves the whole paragraph above the paragraph before it","Selects the text from the cursor to the start of the paragraph","Moves the cursor to the start of the previous paragraph","Promotes the paragraph to a higher heading level"],"answer":0,"explanation":"Alt + Shift + Up/Down moves the paragraph itself up or down. Ctrl + Shift + Up selects to the paragraph start, Ctrl + Up only moves the cursor, and Alt + Shift + Left promotes a heading.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-458","question":"In MS Word, which shortcut opens the Word Count dialog showing pages, words, characters and paragraphs?","options":["Ctrl + Shift + W","Ctrl + Shift + C","Alt + Shift + W","Ctrl + Shift + G"],"answer":3,"explanation":"Ctrl + Shift + G opens Word Count. Ctrl + Shift + W applies a words-only underline and Ctrl + Shift + C copies formatting.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-459","question":"After reopening a long Word document, the user wants to jump straight back to the place where the last change was made. Which shortcut does this?","options":["Shift + F5","Ctrl + End","Ctrl + Home","Alt + F5"],"answer":0,"explanation":"Shift + F5 moves to the previous editing locations, including the last edit after the document is reopened. Ctrl + End and Ctrl + Home only go to the end or start.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-460","question":"In MS Word, what does Ctrl + Delete remove?","options":["The word to the left of the cursor","The whole line the cursor is on","The whole paragraph the cursor is in","The word to the right of the cursor"],"answer":3,"explanation":"Ctrl + Delete deletes forward to the end of the word on the right of the cursor, while Ctrl + Backspace deletes the word on the left.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL"},
  {"id":"comp-ms-office-internet-461","question":"A legal draft in Word must show a number beside every line in the left margin so that reviewers can refer to, say, line 23 on page 4. Which feature should be used?","options":["Numbering (Home tab)","Page Number (Insert tab)","Line Numbers (Layout tab)","Footnote (References tab)"],"answer":2,"explanation":"Line Numbers prints a count beside each line in the margin, optionally restarting each page or section. The Numbering button only numbers paragraphs as a list.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-462","question":"A clerk types the same four-line disclaimer at the end of many Word letters every day. Which feature stores it as a reusable block that can be picked from a gallery or inserted by typing its name and pressing F3?","options":["Format Painter (Home tab)","Quick Parts (AutoText)","Mail Merge (Mailings tab)","AutoCorrect (Options)"],"answer":1,"explanation":"Quick Parts stores AutoText building blocks; typing an entry's name and pressing F3 inserts it. Format Painter copies only formatting, not text.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-463","question":"In MS Excel, what does Ctrl + Shift + & do to the selected cells?","options":["Removes every border from the selected cells","Applies the currency format with the ₹ sign","Joins the text of the selected cells with &","Applies an outline border around the selection"],"answer":3,"explanation":"Ctrl + Shift + & adds an outline border around the selection and Ctrl + Shift + _ removes borders. & joins text only inside a formula.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-464","question":"In Excel, A1 contains 1234.567 in General format. It is selected and Ctrl + Shift + ! is pressed. What does the cell show?","options":["1234.57","1,234.57","1,235","1.23E+03"],"answer":1,"explanation":"Ctrl + Shift + ! applies the Number format with two decimal places and a thousands separator, so the value displays as 1,234.57 (the stored value stays 1234.567).","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-465","question":"In Excel, column A has entries in A1:A500 with no blank cells. The cursor is in A1 and Ctrl + Down Arrow is pressed. Where does it go?","options":["A2","A1048576","A500","A501"],"answer":2,"explanation":"Ctrl + arrow jumps to the edge of the current data region, here the last filled cell, A500. It would go to the last row of the sheet only if the cells below A1 were empty.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-466","question":"In a large Excel sheet, what is a quick way to jump straight to cell T4500 without scrolling?","options":["Type T4500 in the Name Box and press Enter","Press Ctrl + Home and then the Down Arrow key","Turn on Freeze Panes at row 4500 of column T","Press Ctrl + End and then the Left Arrow key"],"answer":0,"explanation":"The Name Box, to the left of the formula bar, accepts a cell address and jumps there (as does Go To, Ctrl + G). Ctrl + Home and Ctrl + End go to the start or the last used cell.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-467","question":"An officer selects B2:B40 in Excel and needs their total and average at once, without typing any formula. Where can they be seen?","options":["In the formula bar above the column letters","In the Name Box to the left of the formula bar","In the status bar at the bottom of the window","In the title bar at the top of the window"],"answer":2,"explanation":"For a selection of numbers, the status bar shows Average, Count and Sum by default, and more statistics can be added by right-clicking it.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-468","question":"In Excel, A1 = Branch, B1 = Delhi and C1 = 2024. A1:C1 is selected and Merge & Center is applied, and the warning is accepted. What does the merged cell show?","options":["Branch Delhi 2024, joined with spaces","Only 2024, the last value in the range","Nothing, as all three values are cleared","Only Branch, centred across the merged cell"],"answer":3,"explanation":"Merging keeps only the upper-left value and discards the rest after a warning. To join texts, use a formula such as =A1&\" \"&B1&\" \"&C1.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-469","question":"A long branch name must stay on ONE line inside a narrow Excel column, with its font made smaller automatically to fit. Which cell format option does this?","options":["Wrap text","Shrink to fit","Merge cells","AutoFit Column Width"],"answer":1,"explanation":"Shrink to fit reduces the displayed font size so the text fits the cell width. Wrap text splits it over several lines, and AutoFit widens the column instead.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-470","question":"A sheet has names in column A and balances in column B. A user selects only column B, sorts it largest to smallest, and chooses Continue with the current selection. What is the result?","options":["Balances get reordered but names stay put, so the rows no longer match","Names and balances are both sorted together, keeping each row intact","Excel sorts nothing, since one column alone cannot be sorted","Names are sorted A to Z and balances largest to smallest"],"answer":0,"explanation":"Continue with the current selection sorts only the selected column, breaking the link between each name and its balance. Expand the selection keeps whole rows together.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-471","question":"Data > Subtotal is run on a list to give a total for each region, but the result shows several separate subtotals for the same region. What was missed?","options":["The list was not first formatted as an Excel Table","The list was not first sorted by the region column","The region column was not set to the Text format","Filters were not turned on before running Subtotal"],"answer":1,"explanation":"The Subtotal command inserts a total each time the value in the grouping column changes, so the data must be sorted by that column first to bring each region together.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-472","question":"Twelve monthly sheets with the same layout must be combined into one summary sheet that adds matching figures by position or by label. Which Excel feature does this?","options":["Consolidate","Flash Fill","Text to Columns","Remove Duplicates"],"answer":0,"explanation":"Data > Consolidate combines ranges from several sheets using a function such as Sum, matching them by position or by row and column labels.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-473","question":"One Excel chart must show monthly sales (in thousands of rupees) as columns and growth percentage (single digits) as a line, with both readable. What should be used?","options":["A pie chart with both series shown in the same pie","A single-axis line chart with both series as lines","A combo chart with the growth series on a secondary axis","Two sparklines placed in one cell next to each other"],"answer":2,"explanation":"On one axis, the small percentages would sit flat near zero. A combo chart plots one series as columns and the other as a line on its own secondary axis.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-474","question":"Figures in the source data of an Excel PivotTable are corrected, but the PivotTable still shows the old totals. What is needed?","options":["Press F9 to recalculate","Re-sort the source data","Turn off AutoFilter","Refresh the PivotTable"],"answer":3,"explanation":"A PivotTable works from a stored cache of the source, so it updates only when refreshed (Refresh or Alt + F5). F9 recalculates formulas but not PivotTables.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-475","question":"In Excel Data Validation, which Error Alert style shows a message asking whether to continue, and accepts the invalid entry if the user clicks Yes?","options":["Stop","Information","Warning","Input Message"],"answer":2,"explanation":"Stop refuses invalid data, Warning asks Continue? and accepts it on Yes, and Information only informs and accepts it on OK. Input Message is a hint shown before typing, not an alert.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-476","question":"In PowerPoint 2013 and later, what is the default slide size for a new blank presentation?","options":["Standard (4:3)","A4 Paper","Widescreen (16:10)","Widescreen (16:9)"],"answer":3,"explanation":"Since PowerPoint 2013 new presentations are widescreen 16:9; the older 4:3 Standard size can still be chosen in Slide Size.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains"},
  {"id":"comp-ms-office-internet-477","question":"A 60-slide PowerPoint deck needs its slides grouped under named, collapsible headings such as Introduction, Results and Way Forward in Slide Sorter view. Which feature does this?","options":["Sections","Hide Slide","Handout Master","Slide Layout"],"answer":0,"explanation":"Sections divide a deck into named groups that can be collapsed, moved or printed together. Hide Slide only skips a slide during the show.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL"},
  {"id":"comp-ms-office-internet-478","question":"Match the file extension with its type: 1. .odt 2. .ods 3. .odp 4. .xps; a. Microsoft's fixed-layout document format b. OpenDocument presentation c. OpenDocument spreadsheet d. OpenDocument text document","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-a, 2-c, 3-b, 4-d"],"answer":1,"explanation":"The OpenDocument formats (used by LibreOffice and openable in Office) are .odt for text, .ods for spreadsheets and .odp for presentations. .xps is Microsoft's fixed-layout format, similar to PDF.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-479","question":"An office replaces its old hub with a switch. Why does network traffic on each computer's cable drop?","options":["A switch compresses every frame so that less data travels on each of the cables","A switch blocks all broadcast traffic, so no computer gets a broadcast again","A switch learns MAC addresses and sends frames only to the receiver's port","A switch encrypts the frames, so the other computers can no longer read them"],"answer":2,"explanation":"A hub repeats every frame out of all ports. A switch keeps a MAC address table and forwards unicast frames only to the right port, though it still floods broadcasts.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-480","question":"Taking 1 KB = 1024 bytes, how many bits are there in a 2 KB file?","options":["2048","16000","8192","16384"],"answer":3,"explanation":"2 KB = 2 × 1024 = 2048 bytes, and each byte has 8 bits, so 2048 × 8 = 16384 bits. 8192 is the number of bits in 1 KB.","difficulty":"moderate","source":"SSC CGL · SBI Clerk"},
  {"id":"comp-ms-office-internet-481","question":"A phone connected by Bluetooth to a smartwatch and wireless earbuds, all within a few metres of the user, forms which type of network?","options":["LAN","PAN","MAN","WAN"],"answer":1,"explanation":"A Personal Area Network links devices around one person over a few metres, typically using Bluetooth. A LAN covers a building or campus.","difficulty":"moderate","source":"SSC CHSL · SBI Clerk"},
  {"id":"comp-ms-office-internet-482","question":"A bank runs a private website for circulars and leave forms that only its own employees can open, using the same web technology as the internet. This is called an:","options":["Intranet","Extranet","Internet","Ethernet"],"answer":0,"explanation":"An intranet is an organisation's private network using internet protocols, for staff only. An extranet extends part of it to outside partners such as vendors.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk"},
  {"id":"comp-ms-office-internet-483","question":"In a BitTorrent download, a file is received in pieces from many users' computers, while the same computer also uploads pieces to others. Which network model is this?","options":["Client-server","Mainframe terminal","Star topology","Peer-to-peer"],"answer":3,"explanation":"In peer-to-peer networking every computer acts as both client and server, sharing pieces directly. In client-server, central servers provide the service to clients.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-484","question":"Match the cloud service with its model: 1. Gmail used by a bank's staff 2. Renting virtual servers and storage to run the bank's own operating system 3. A platform where developers just upload code and the provider runs it; a. IaaS b. PaaS c. SaaS","options":["1-a, 2-c, 3-b","1-c, 2-b, 3-a","1-c, 2-a, 3-b","1-b, 2-a, 3-c"],"answer":2,"explanation":"Ready-to-use software is SaaS, raw virtual machines and storage are IaaS, and a managed environment for deploying your own code is PaaS.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-485","question":"In e-mail and online chat etiquette (netiquette), what does typing a whole message IN CAPITAL LETTERS usually suggest?","options":["Urgency approved by a manager","Shouting","A formal legal notice","An automatic system message"],"answer":1,"explanation":"Writing in all capitals is read as shouting and is considered rude; important words are better shown with bold or a clear subject line.","difficulty":"moderate","source":"SSC CHSL · SBI Clerk"},
  {"id":"comp-ms-office-internet-486","question":"An antivirus program finds a suspicious file and moves it into quarantine. What does this mean?","options":["The file is isolated where it cannot run, and can be restored or deleted later","The file is immediately and permanently deleted from the disk with no way to restore it","The file is uploaded to the police cyber cell along with the details of the user","The file is repaired and put back in its place, so it is now safe to open"],"answer":0,"explanation":"Quarantine locks a suspect file away so it cannot execute, while keeping it in case it was a false alarm. Cleaning or deletion is a separate choice.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk"},
  {"id":"comp-ms-office-internet-487","question":"A security team opens a suspicious e-mail attachment inside an isolated environment where any harm it does cannot reach the real system, and watches what it does. This environment is called a:","options":["Honeypot","Sandbox","Firewall","Proxy"],"answer":1,"explanation":"A sandbox runs untrusted code in isolation to observe its behaviour safely. A honeypot is a decoy that lures attackers, not a place to test files.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-488","question":"The WannaCry ransomware of May 2017 spread mostly through Windows computers that had not been updated. Why?","options":["It used a flaw that no vendor had heard of, so no patch existed anywhere at that time","It spread only through infected USB drives, which updated systems refused to read","It exploited a Windows file-sharing (SMB) flaw for which a patch had been released earlier","It needed the user to type an administrator password, which updates had removed"],"answer":2,"explanation":"WannaCry used the EternalBlue exploit against SMBv1; Microsoft had issued a fix (MS17-010) in March 2017, so patched systems were protected. It was not a zero-day at the time.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-489","question":"A bank moves from a 4-digit to a 6-digit numeric PIN. How many times larger is the number of possible PINs?","options":["100 times","2 times","10 times","50 times"],"answer":0,"explanation":"A 4-digit PIN has 10^4 = 10,000 combinations and a 6-digit PIN 10^6 = 1,000,000, which is 10^2 = 100 times as many.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-490","question":"In a Caesar cipher each letter is replaced by the letter 3 places later in the alphabet. What is the word BANK after encryption?","options":["DCPM","YXKH","EDNQ","EDQN"],"answer":3,"explanation":"B→E, A→D, N→Q and K→N, giving EDQN. Shifting backwards by 3 would give YXKH. Such simple substitution ciphers are easy to break.","difficulty":"hard","source":"SBI Clerk Mains · SSC CGL"},
  {"id":"comp-ms-office-internet-491","question":"A bank publishes the SHA-256 hash of a downloadable app. A customer changes just one character in the downloaded file and hashes it again. What will the new hash look like?","options":["Identical to the published hash, as the size is unchanged","Different from the published hash in one character only","Completely different from the published hash","The same as the published hash but one character shorter"],"answer":2,"explanation":"Good hash functions show the avalanche effect: a tiny change in input changes the output unpredictably and completely, while the length stays fixed (64 hex characters for SHA-256).","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-492","question":"Malware hidden inside a pirated game gives an attacker full remote control of the victim's computer, including the webcam and files. It is best described as a:","options":["Remote Access Trojan (RAT)","Boot sector virus on the disk","Logic bomb with a timer","Adware program with pop-ups"],"answer":0,"explanation":"A RAT is a Trojan that opens a hidden backdoor so the attacker can control the system remotely. A logic bomb only waits for a trigger condition.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-493","question":"A ransom note suddenly appears on one computer in a branch network. What should be done first?","options":["Pay the ransom quickly before the price goes up","Disconnect that computer from the network at once","Restart the computer several times to clear it","Copy its files to the shared drive to save them"],"answer":1,"explanation":"Isolating the infected machine stops the ransomware spreading to shares and other PCs. Paying does not guarantee recovery, and copying files can spread the infection.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-494","question":"Arrange these Wi-Fi security standards from the weakest to the strongest:","options":["WPA, WEP, WPA2, WPA3","WEP, WPA2, WPA, WPA3","WPA3, WPA2, WPA, WEP","WEP, WPA, WPA2, WPA3"],"answer":3,"explanation":"WEP (1990s) is easily cracked, WPA was a stop-gap, WPA2 brought AES encryption, and WPA3 (2018) is the newest and strongest.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-495","question":"A branch hides its Wi-Fi network name (SSID) and believes the network is now secure. Why is this weak protection?","options":["Hiding the SSID turns off encryption, so all the data travels in plain form","Hiding the SSID makes the router accept any password typed by a device","The SSID still travels in normal Wi-Fi traffic and can be seen with simple tools","A hidden SSID can be used only on 2.4 GHz, which has no security at all"],"answer":2,"explanation":"A hidden SSID is left out of beacons but still appears when devices connect, so attackers find it easily. Real protection comes from WPA2/WPA3 with a strong passphrase.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"comp-ms-office-internet-496","question":"Who sent the first e-mail between two computers on ARPANET in 1971 and chose the @ sign to separate the user from the host?","options":["Tim Berners-Lee","Ray Tomlinson","Vint Cerf","Bob Kahn"],"answer":1,"explanation":"Ray Tomlinson created network e-mail on ARPANET in 1971 and used @. Tim Berners-Lee invented the World Wide Web, and Cerf and Kahn designed TCP/IP.","difficulty":"hard","source":"SBI Clerk Mains · SSC CGL"},
  {"id":"comp-ms-office-internet-497","question":"Public internet access in India was launched on 15 August 1995 by which organisation?","options":["VSNL","BSNL","MTNL","ERNET"],"answer":0,"explanation":"Videsh Sanchar Nigam Limited (VSNL) launched public internet service in India on 15 August 1995. ERNET earlier connected only academic and research institutions.","difficulty":"hard","source":"SBI Clerk Mains · SSC CGL"},
  {"id":"comp-ms-office-internet-498","question":"Roughly how many distinct addresses does the IPv4 address space allow?","options":["About 4.3 million","About 65 thousand","About 16 million","About 4.3 billion"],"answer":3,"explanation":"IPv4 uses 32 bits, giving 2^32 = 4,294,967,296 addresses, about 4.3 billion. The shortage of these led to NAT and to 128-bit IPv6.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-499","question":"Why has Telnet largely been replaced by SSH for logging in to remote servers?","options":["Telnet works only inside a single LAN, while SSH also works over the internet","Telnet sends data, including passwords, as plain text, while SSH encrypts it","Telnet cannot run commands on the server, while SSH can run them","Telnet needs a graphical screen, while SSH works on a text console"],"answer":1,"explanation":"Telnet (port 23) has no encryption, so anyone capturing traffic can read passwords. SSH (port 22) gives the same remote login over an encrypted channel.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-500","question":"Which statement about SSL and TLS is correct?","options":["TLS is outdated and HTTPS now uses SSL 3.0, the latest version of the protocol","SSL and TLS are two names for exactly the same current protocol version","SSL is outdated; HTTPS now uses TLS, though people still say SSL","TLS protects only e-mail, while SSL protects only web browsing"],"answer":2,"explanation":"TLS succeeded SSL; all SSL versions are deprecated as insecure, and modern HTTPS uses TLS 1.2 or 1.3. People still say 'SSL certificate' out of habit.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains"},
  {"id":"comp-ms-office-internet-501","question":"A branch's phone calls are carried as data packets over its internet connection instead of the traditional telephone line. This technology is called:","options":["VoIP","IPTV","VPN","PSTN"],"answer":0,"explanation":"Voice over Internet Protocol (VoIP) digitises speech into IP packets. PSTN is the traditional circuit-switched telephone network, and IPTV carries television over IP.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL"},
];

export default questions;
